insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('c7000000-0000-0000-0000-000000000001', 'ukmla', '1a2b9b3d-7d5e-401b-b8a2-2935d5e821ec',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('c7000000-0000-0000-0000-000000000001', 'A', 'Explain the diagnosis of irritable bowel syndrome and advise dietary modification (e.g. reduced caffeine and fizzy drinks, regular meals) as first-line management', true, 'Correct. This presentation meets the Rome criteria for IBS-D (abdominal pain related to defecation with altered stool form/frequency) with normal inflammatory markers and calprotectin excluding organic disease, so a positive clinical diagnosis can be made and first-line management is dietary and lifestyle advice.', 1),
('c7000000-0000-0000-0000-000000000001', 'B', 'Arrange an urgent colonoscopy to exclude inflammatory bowel disease before making a diagnosis', false, 'Ruled out because with no red flags (no bleeding, weight loss, nocturnal symptoms), normal calprotectin and normal inflammatory markers, invasive investigation is not required to diagnose IBS, which is a positive clinical diagnosis based on symptom pattern.', 2),
('c7000000-0000-0000-0000-000000000001', 'C', 'Start a course of oral prednisolone for suspected microscopic colitis', false, 'Ruled out because there is no indication of colitis; steroids are not first-line and would not be started without histological confirmation, which is not being pursued here as there are no red flags.', 3),
('c7000000-0000-0000-0000-000000000001', 'D', 'Reassure her that no follow-up or explanation is needed as this will resolve spontaneously', false, 'Ruled out because IBS is a chronic relapsing condition that benefits from explanation, dietary advice and a clear plan for symptomatic treatment; simple reassurance without guidance is inadequate.', 4),
('c7000000-0000-0000-0000-000000000001', 'E', 'Refer for faecal microbiota transplantation', false, 'Ruled out because this is an unproven and inappropriate intervention for IBS; it is not a recognised first-line or even standard therapy for this condition.', 5),
('c7000000-0000-0000-0000-000000000002', 'A', 'A stimulant laxative such as senna as first-line long-term therapy', false, 'Ruled out because stimulant laxatives are recommended only for short-term use or if other laxatives are ineffective, not as first-line long-term therapy in IBS-C.', 1),
('c7000000-0000-0000-0000-000000000002', 'B', 'A bulk-forming laxative such as ispaghula husk, titrated to response', true, 'Correct. In IBS-C, once dietary measures alone are insufficient, a bulk-forming laxative is the recommended first-line pharmacological step; osmotic laxatives are used if this is not tolerated or ineffective, with stimulant laxatives reserved for short-term use if needed.', 2),
('c7000000-0000-0000-0000-000000000002', 'C', 'Loperamide taken regularly to reduce bowel frequency', false, 'Ruled out because loperamide is an antimotility agent used for diarrhoea-predominant IBS, not constipation-predominant IBS; it would worsen his symptoms.', 3),
('c7000000-0000-0000-0000-000000000002', 'D', 'Long-term codeine phosphate for symptom control', false, 'Ruled out because opioids such as codeine cause and worsen constipation and are not appropriate management for IBS-C.', 4),
('c7000000-0000-0000-0000-000000000002', 'E', 'Referral for subtotal colectomy', false, 'Ruled out because surgery has no role in the routine management of IBS-C, which is managed medically and with lifestyle measures.', 5),
('c7000000-0000-0000-0000-000000000003', 'A', 'Arrange an urgent CT abdomen and pelvis to exclude colorectal malignancy before any treatment', false, 'Ruled out because there are no red flag features (no bleeding, no weight loss, no palpable mass) to suggest malignancy; urgent imaging is not required before a trial of standard laxative therapy in this low-risk presentation.', 1),
('c7000000-0000-0000-0000-000000000003', 'B', 'Perform manual evacuation under general anaesthetic', false, 'Ruled out because this is a disproportionately invasive intervention for simple constipation that has not yet had an adequate trial of oral laxatives; digital rectal examination alone (already done) is usually sufficient at this stage.', 2),
('c7000000-0000-0000-0000-000000000003', 'C', 'Advise her to stop amlodipine immediately without medical review', false, 'Ruled out because although calcium channel blockers can contribute to constipation, abruptly stopping antihypertensive medication without review risks uncontrolled hypertension; medication review should be considered but is not the immediate priority over starting a laxative.', 3),
('c7000000-0000-0000-0000-000000000003', 'D', 'Start an osmotic laxative such as a macrogol', true, 'Correct. When dietary and lifestyle measures have failed in simple chronic constipation without red flags, an osmotic laxative (e.g. macrogol) is the appropriate first-line pharmacological treatment before considering stimulant laxatives or further escalation.', 4),
('c7000000-0000-0000-0000-000000000003', 'E', 'Start regular codeine phosphate for symptomatic relief', false, 'Ruled out because opioids worsen constipation and are contraindicated as a treatment for it.', 5),
('c7000000-0000-0000-0000-000000000004', 'A', 'Oesophageal carcinoma', false, 'Ruled out because malignancy typically causes progressive dysphagia for solids preceding liquids (mechanical obstruction) and would usually show a mucosal mass or stricture on endoscopy, which was normal here; the barium findings are also classic for achalasia rather than malignancy.', 1),
('c7000000-0000-0000-0000-000000000004', 'B', 'Gastro-oesophageal reflux disease with peptic stricture', false, 'Ruled out because a peptic stricture typically causes dysphagia predominantly for solids and would be visible endoscopically as a mechanical narrowing, not the smooth tapering and proximal dilation seen here.', 2),
('c7000000-0000-0000-0000-000000000004', 'C', 'Achalasia', true, $x$Correct. Dysphagia to both solids and liquids from onset, regurgitation, weight loss and a 'bird's beak' tapering of the distal oesophagus on barium swallow with a dilated oesophageal body are classic for achalasia, caused by loss of inhibitory ganglion cells in the lower oesophageal sphincter leading to failure of relaxation and absent peristalsis.$x$, 3),
('c7000000-0000-0000-0000-000000000004', 'D', 'Diffuse oesophageal spasm', false, $x$Ruled out because this typically causes intermittent chest pain and dysphagia with a 'corkscrew' appearance on barium swallow, rather than the progressive dysphagia to both textures with bird's beak tapering and proximal dilation described here.$x$, 4),
('c7000000-0000-0000-0000-000000000004', 'E', 'Plummer-Vinson syndrome', false, $x$Ruled out because this is associated with iron-deficiency anaemia and oesophageal webs causing dysphagia for solids, not the bird's beak appearance and proximal dilation characteristic of achalasia.$x$, 5),
('c7000000-0000-0000-0000-000000000005', 'A', 'Achalasia', false, $x$Ruled out because achalasia typically shows a bird's beak tapering with a dilated oesophageal body on barium swallow and absent peristalsis on manometry, rather than the corkscrew pattern of simultaneous contractions described here.$x$, 1),
('c7000000-0000-0000-0000-000000000005', 'B', 'Stable angina', false, 'Ruled out because this has already been excluded by normal exercise ECG and normal coronary angiography; the barium swallow findings instead point to an oesophageal motility disorder.', 2),
('c7000000-0000-0000-0000-000000000005', 'C', 'Eosinophilic oesophagitis', false, 'Ruled out because this typically presents with solid food dysphagia and food bolus obstruction in a younger patient with atopy, and endoscopy usually shows rings, furrows or strictures, none of which are described here.', 3),
('c7000000-0000-0000-0000-000000000005', 'D', 'Gastro-oesophageal reflux disease', false, 'Ruled out because simple reflux does not typically cause a corkscrew oesophagus on barium swallow or dysphagia to both solids and liquids; the described findings are specific for a spastic motility disorder.', 4),
('c7000000-0000-0000-0000-000000000005', 'E', 'Diffuse oesophageal spasm', true, 'Correct. Intermittent chest pain often triggered by temperature extremes, dysphagia to solids and liquids, a normal cardiac work-up, and a corkscrew appearance with simultaneous non-peristaltic contractions on barium swallow are characteristic of diffuse oesophageal spasm.', 5),
('c7000000-0000-0000-0000-000000000006', 'A', 'Peptic ulcer disease with gastric outlet obstruction', false, 'Ruled out because endoscopy was normal, excluding a mechanical ulcer-related outlet obstruction; the gastric emptying study confirms a motility rather than a structural cause.', 1),
('c7000000-0000-0000-0000-000000000006', 'B', 'Zollinger-Ellison syndrome', false, 'Ruled out because this gastrin-secreting tumour typically causes recurrent peptic ulceration and diarrhoea from gastric acid hypersecretion, not delayed gastric emptying with a normal endoscopy.', 2),
('c7000000-0000-0000-0000-000000000006', 'C', 'Diabetic gastroparesis', true, 'Correct. Long-standing poorly controlled diabetes with other microvascular complications (neuropathy, retinopathy), early satiety, bloating and vomiting of undigested food, with a normal endoscopy and confirmed delayed gastric emptying on scintigraphy, is characteristic of diabetic gastroparesis caused by autonomic neuropathy affecting gastric motility.', 3),
('c7000000-0000-0000-0000-000000000006', 'D', 'Coeliac disease', false, 'Ruled out because this typically causes malabsorptive symptoms such as diarrhoea, weight loss and bloating related to gluten, with duodenal villous atrophy on biopsy, rather than isolated delayed gastric emptying.', 4),
('c7000000-0000-0000-0000-000000000006', 'E', 'Cyclical vomiting syndrome', false, 'Ruled out because this is a diagnosis of exclusion characterised by discrete episodic vomiting with symptom-free intervals in the absence of an identifiable structural or metabolic cause, whereas here there is a clear underlying cause (diabetic autonomic neuropathy) and objectively delayed gastric emptying.', 5),
('c7000000-0000-0000-0000-000000000007', 'A', 'Microscopic colitis', false, 'Ruled out because colonic biopsies were unremarkable, which would be expected to show characteristic lymphocytic or collagenous infiltration if microscopic colitis were present.', 1),
('c7000000-0000-0000-0000-000000000007', 'B', 'Bile acid diarrhoea', true, 'Correct. Chronic watery, often nocturnal diarrhoea following cholecystectomy, with normal colonoscopy and biopsies excluding microscopic colitis and IBD, and an abnormal SeHCAT scan showing excessive bile acid loss, is characteristic of bile acid diarrhoea (bile acid malabsorption), which can be precipitated by altered enterohepatic bile acid circulation after gallbladder removal.', 2),
('c7000000-0000-0000-0000-000000000007', 'C', 'Irritable bowel syndrome with diarrhoea', false, 'Ruled out because IBS is a diagnosis made after excluding organic causes, and here a specific abnormality (elevated bile acid loss on SeHCAT) has been identified, providing a more specific diagnosis and directing targeted treatment.', 3),
('c7000000-0000-0000-0000-000000000007', 'D', 'Coeliac disease', false, 'Ruled out because coeliac serology was normal, making this diagnosis unlikely without further biopsy evidence of villous atrophy.', 4),
('c7000000-0000-0000-0000-000000000007', 'E', 'Small intestinal bacterial overgrowth', false, 'Ruled out because there is no supportive history (e.g. prior small bowel surgery, structural abnormality) and the specific diagnostic test performed (SeHCAT) instead confirms excess bile acid loss as the cause.', 5),
('c7000000-0000-0000-0000-000000000008', 'A', 'Colonoscopy with biopsy', false, 'Ruled out because this is invasive, carries risk (including perforation) in acute severe colitis, and is not required as a first investigation when stool toxin testing can confirm the diagnosis; endoscopy is reserved for atypical or complicated cases.', 1),
('c7000000-0000-0000-0000-000000000008', 'B', 'Serum amylase', false, 'Ruled out because there is no suggestion of pancreatitis here; the clinical picture (antibiotic exposure, diarrhoea, systemic inflammation) points to an infective colitis, not pancreatic pathology.', 2),
('c7000000-0000-0000-0000-000000000008', 'C', 'Abdominal ultrasound', false, 'Ruled out because this is not the investigation of choice for diagnosing C. difficile infection; stool toxin testing is required, with CT reserved if complications such as toxic megacolon are suspected.', 3),
('c7000000-0000-0000-0000-000000000008', 'D', 'Blood cultures alone, without stool testing', false, 'Ruled out because although blood cultures may be taken as part of a septic work-up, they do not confirm C. difficile infection; stool toxin testing is required to establish the diagnosis.', 4),
('c7000000-0000-0000-0000-000000000008', 'E', 'Stool sample for Clostridioides difficile toxin testing', true, 'Correct. New-onset diarrhoea with systemic inflammatory features in a hospitalised elderly patient following recent broad-spectrum antibiotic exposure is highly suggestive of Clostridioides difficile infection, and stool toxin testing (or PCR/toxin combination per local protocol) is the key investigation to confirm this and guide isolation and treatment.', 5),
('c7000000-0000-0000-0000-000000000009', 'A', 'High-dose intravenous proton pump inhibitor alone, with no antibiotics', false, 'Ruled out because while PPI therapy is appropriate for peptic ulcer bleeding, in suspected variceal haemorrhage the priority is terlipressin and antibiotics; withholding antibiotics in a cirrhotic patient with GI bleeding increases the risk of infection and mortality.', 1),
('c7000000-0000-0000-0000-000000000009', 'B', 'Immediate surgical oesophagectomy', false, 'Ruled out because surgery is not the initial management of variceal bleeding; endoscopic band ligation (or sclerotherapy) is the definitive first-line intervention after pharmacological and resuscitative measures, with a Sengstaken-Blakemore tube or TIPS reserved for uncontrolled bleeding.', 2),
('c7000000-0000-0000-0000-000000000009', 'C', 'Oral iron replacement and outpatient follow-up', false, 'Ruled out because this is an acute, life-threatening upper gastrointestinal haemorrhage requiring emergency inpatient management, not outpatient treatment.', 3),
('c7000000-0000-0000-0000-000000000009', 'D', 'Intravenous terlipressin and prophylactic broad-spectrum antibiotics', true, 'Correct. In a patient with known chronic liver disease and signs of portal hypertension presenting with haematemesis, variceal bleeding must be assumed until proven otherwise; terlipressin (to reduce splanchnic blood flow and portal pressure) and prophylactic antibiotics (to reduce mortality and prevent bacterial infection/spontaneous bacterial peritonitis) should be started immediately alongside resuscitation, ahead of endoscopy.', 4),
('c7000000-0000-0000-0000-000000000009', 'E', 'Withhold blood transfusion until haemoglobin falls below 50 g/L', false, 'Ruled out because in acute upper GI bleeding a restrictive transfusion threshold of around 70 g/L (adjusted for haemodynamic status and comorbidities) is used, not waiting until haemoglobin falls to 50 g/L, which would risk haemodynamic collapse.', 5),
('c7000000-0000-0000-0000-000000000010', 'A', 'Diverticular bleeding', true, 'Correct. Sudden, painless, brisk lower GI bleeding in an older patient with known diverticulosis is the classic presentation of diverticular haemorrhage, which arises from erosion of a vessel at the neck of a diverticulum and is the most common cause of significant lower GI bleeding in this age group.', 1),
('c7000000-0000-0000-0000-000000000010', 'B', 'Ischaemic colitis', false, 'Ruled out because this typically presents with abdominal pain preceding bleeding (often in a patient with vascular risk factors or hypotensive episodes), rather than the painless bleeding described here.', 2),
('c7000000-0000-0000-0000-000000000010', 'C', 'Haemorrhoids', false, 'Ruled out because haemorrhoidal bleeding is typically small volume, bright red blood coating the stool or on wiping, rather than the described bleeding with clots; also less likely to be the cause given known diverticulosis and his age.', 3),
('c7000000-0000-0000-0000-000000000010', 'D', 'Colorectal malignancy', false, 'Ruled out as the most likely cause here because the acute, painless, large-volume bleeding pattern with known diverticulosis is far more consistent with diverticular haemorrhage, although malignancy should still be excluded on subsequent colonoscopy if not already done recently.', 4),
('c7000000-0000-0000-0000-000000000010', 'E', 'Anal fissure', false, 'Ruled out because fissures typically cause pain on defecation with small amounts of bright red blood, not the painless, larger volume bleeding described.', 5),
('c7000000-0000-0000-0000-000000000011', 'A', 'Sigmoid volvulus', false, $x$Ruled out because this typically causes large bowel obstruction with a characteristic 'coffee bean' sign on abdominal X-ray, not dilated small bowel loops with valvulae conniventes.$x$, 1),
('c7000000-0000-0000-0000-000000000011', 'B', 'Adhesional small bowel obstruction', true, 'Correct. A history of previous abdominal/pelvic surgery, colicky central pain, distension, absolute constipation, faeculent vomiting and dilated small bowel loops with valvulae conniventes on X-ray and no rectal gas is the classic picture of small bowel obstruction, and adhesions from prior surgery are the most common cause in this context.', 2),
('c7000000-0000-0000-0000-000000000011', 'C', 'Acute pancreatitis', false, 'Ruled out because although this can cause an ileus with vomiting and abdominal pain, it would not typically produce the mechanical obstruction pattern described (absolute constipation, faeculent vomiting, dilated small bowel loops); serum lipase/amylase would clarify but the clinical and radiological picture here is obstruction, not pancreatitis.', 3),
('c7000000-0000-0000-0000-000000000011', 'D', 'Ulcerative colitis flare', false, 'Ruled out because UC typically presents with bloody diarrhoea rather than absolute constipation and small bowel obstruction; it would not produce this radiological pattern.', 4),
('c7000000-0000-0000-0000-000000000011', 'E', 'Coeliac disease', false, 'Ruled out because this causes malabsorptive diarrhoea and does not cause mechanical bowel obstruction.', 5),
('c7000000-0000-0000-0000-000000000012', 'A', 'Start a proton pump inhibitor and admit for observation without surgical referral', false, 'Ruled out because a perforated viscus with pneumoperitoneum and peritonitis is a surgical emergency requiring urgent operative management, not conservative observation alone.', 1),
('c7000000-0000-0000-0000-000000000012', 'B', 'Arrange an outpatient upper GI endoscopy in the next few days', false, 'Ruled out because this presentation represents an acute perforation with peritonitis requiring emergency in-hospital management, not deferred outpatient investigation; endoscopy is also relatively contraindicated in perforation due to risk of worsening free air/leak.', 2),
('c7000000-0000-0000-0000-000000000012', 'C', 'Give oral fluids and discharge with safety-netting advice', false, 'Ruled out because this patient has signs of a surgical abdomen (peritonitis, free air) and haemodynamic compromise, and discharge would be dangerous and inappropriate.', 3),
('c7000000-0000-0000-0000-000000000012', 'D', 'Urgent surgical referral for emergency laparotomy, with IV fluids, broad-spectrum antibiotics and analgesia started immediately', true, 'Correct. Sudden severe abdominal pain with a rigid abdomen, peritonism and free air under the diaphragm on erect chest X-ray in a patient with a history of NSAID use (a major risk factor for peptic ulceration) indicates a perforated peptic ulcer; this is a surgical emergency requiring immediate resuscitation, antibiotics and urgent surgical intervention.', 4),
('c7000000-0000-0000-0000-000000000012', 'E', 'Administer high-dose oral antibiotics only and reassess in 24 hours', false, 'Ruled out because oral antibiotics alone are inadequate for a perforated viscus with peritonitis; this requires IV antibiotics, resuscitation and emergency surgical intervention without delay.', 5),
('c7000000-0000-0000-0000-000000000013', 'A', 'Toxic megacolon complicating acute severe ulcerative colitis, with risk of perforation', true, 'Correct. Severe bloody diarrhoea, systemic toxicity (tachycardia, fever), abdominal distension with reduced bowel sounds, and colonic dilation greater than 6 cm with loss of haustration on AXR in a patient with known UC indicates toxic megacolon, a life-threatening complication carrying a high risk of colonic perforation requiring urgent multidisciplinary (gastroenterology and colorectal surgical) input and IV corticosteroids with close monitoring for non-response.', 1),
('c7000000-0000-0000-0000-000000000013', 'B', 'Simple flare of ulcerative colitis requiring only an increase in oral mesalazine dose', false, 'Ruled out because the degree of systemic toxicity and colonic dilation indicates a life-threatening complication (toxic megacolon), not a routine flare manageable with oral aminosalicylate escalation alone; this requires emergency inpatient management.', 2),
('c7000000-0000-0000-0000-000000000013', 'C', 'Irritable bowel syndrome flare due to stress', false, 'Ruled out because IBS does not cause bloody diarrhoea, systemic toxicity or colonic dilation; the clinical and radiological findings clearly indicate a severe complication of underlying IBD.', 3),
('c7000000-0000-0000-0000-000000000013', 'D', 'Diverticulitis with abscess formation', false, 'Ruled out because the clinical context (known UC, bloody diarrhoea, diffuse colonic dilation) and the pattern of loss of haustration are characteristic of toxic megacolon rather than diverticulitis, which typically causes localised left iliac fossa pain.', 4),
('c7000000-0000-0000-0000-000000000013', 'E', 'Constipation with faecal impaction', false, 'Ruled out because the presentation is of bloody diarrhoea with systemic sepsis and colonic dilation, not constipation; the AXR finding of colonic dilation with loss of haustration in this context indicates megacolon, not impaction.', 5),
('c7000000-0000-0000-0000-000000000014', 'A', $x$Start empirical IV ciprofloxacin immediately for all cases of traveller's diarrhoea$x$, false, $x$Ruled out because most traveller's diarrhoea is self-limiting and does not require antibiotics; IV antibiotics are not first-line and would only be considered in severe systemic illness.$x$, 1),
('c7000000-0000-0000-0000-000000000014', 'B', 'Prescribe loperamide alone without any rehydration, encouraging normal activity', false, 'Ruled out because antimotility agents like loperamide can be used adjunctively in some cases but should not replace oral rehydration, and are generally avoided if there is bloody diarrhoea or high fever due to risk of worsening some infections (e.g. invasive bacterial colitis).', 2),
('c7000000-0000-0000-0000-000000000014', 'C', 'Arrange urgent colonoscopy to investigate the cause', false, $x$Ruled out because this is an acute self-limiting presentation without red flags; invasive investigation is not indicated for routine acute traveller's diarrhoea.$x$, 3),
('c7000000-0000-0000-0000-000000000014', 'D', 'Admit to hospital for IV fluids as an inpatient', false, 'Ruled out because he has only mild dehydration and is tolerating oral fluids; inpatient IV fluid management is unnecessary at this stage and oral rehydration is appropriate.', 4),
('c7000000-0000-0000-0000-000000000014', 'E', 'Advise oral rehydration therapy and safety-net advice, reserving antibiotics for red flag features or if symptoms persist/worsen', true, $x$Correct. Most cases of traveller's diarrhoea (commonly caused by enterotoxigenic E. coli, Campylobacter, or other bacterial/viral pathogens) are self-limiting and managed with oral rehydration; antibiotics are generally reserved for severe, bloody, or persistent cases, or in immunocompromised patients, rather than given routinely to all mild-to-moderate presentations.$x$, 5),
('c7000000-0000-0000-0000-000000000015', 'A', 'Ulcerative colitis', false, $x$Ruled out because UC causes continuous mucosal (not transmural) inflammation typically starting in the rectum and extending proximally, without granulomas or skip lesions, and does not typically affect the terminal ileum (except for mild 'backwash ileitis').$x$, 1),
('c7000000-0000-0000-0000-000000000015', 'B', 'Coeliac disease', false, $x$Ruled out because coeliac disease causes duodenal villous atrophy related to gluten, not terminal ileal transmural inflammation with granulomas; the biopsy findings here are specific to Crohn's disease.$x$, 2),
('c7000000-0000-0000-0000-000000000015', 'C', $x$Crohn's disease$x$, true, $x$Correct. Patchy ('skip lesion') transmural inflammation with granulomas affecting the terminal ileum, associated with weight loss, abdominal pain, mouth ulcers and iron-deficiency anaemia, is classic for Crohn's disease, which can affect any part of the gastrointestinal tract from mouth to anus.$x$, 3),
('c7000000-0000-0000-0000-000000000015', 'D', 'Infective ileocolitis (e.g. Yersinia)', false, $x$Ruled out because although infective causes can mimic Crohn's disease, the chronicity (4 months), granulomatous transmural inflammation and skip lesions on biopsy are characteristic of Crohn's disease rather than an acute infective process.$x$, 4),
('c7000000-0000-0000-0000-000000000015', 'E', 'Irritable bowel syndrome', false, 'Ruled out because IBS does not cause anaemia, raised inflammatory markers, weight loss or the granulomatous transmural inflammation seen on biopsy; these findings indicate organic inflammatory bowel disease.', 5),
('c7000000-0000-0000-0000-000000000016', 'A', $x$Crohn's disease$x$, false, $x$Ruled out because Crohn's disease causes patchy, transmural inflammation with granulomas and skip lesions, which contrasts with the continuous, mucosa-limited inflammation without granulomas described here.$x$, 1),
('c7000000-0000-0000-0000-000000000016', 'B', 'Infective colitis (e.g. Shigella)', false, 'Ruled out because although infective colitis can cause bloody diarrhoea, the subacute 3-month course and the specific histological findings (crypt architectural distortion, crypt abscesses) are more in keeping with chronic idiopathic IBD (ulcerative colitis) than an acute infective process, which would typically resolve or show different histology.', 2),
('c7000000-0000-0000-0000-000000000016', 'C', 'Ulcerative colitis', true, 'Correct. Continuous mucosal inflammation beginning at the rectum and extending proximally, with crypt abscesses and architectural distortion confined to the mucosa (no granulomas, no transmural involvement) and a clinical picture of bloody diarrhoea with urgency and tenesmus, is characteristic of ulcerative colitis.', 3),
('c7000000-0000-0000-0000-000000000016', 'D', 'Ischaemic colitis', false, $x$Ruled out because this typically occurs in older patients with vascular risk factors, presents more acutely, and shows different histological features (mucosal necrosis, often segmental at 'watershed' areas) rather than the continuous rectal-onset inflammation with crypt abscesses described.$x$, 4),
('c7000000-0000-0000-0000-000000000016', 'E', 'Microscopic colitis', false, 'Ruled out because this causes chronic watery (non-bloody) diarrhoea with a macroscopically normal-appearing colon on endoscopy and characteristic lymphocytic or collagenous infiltration on biopsy, not the macroscopic inflammation and crypt abscesses seen here.', 5),
('c7000000-0000-0000-0000-000000000017', 'A', 'Continue oral mesalazine at the same dose and review again in 2 weeks', false, 'Ruled out because she meets criteria for severe disease requiring hospital admission and IV therapy; continuing outpatient oral mesalazine alone is inadequate and unsafe given the risk of complications such as toxic megacolon.', 1),
('c7000000-0000-0000-0000-000000000017', 'B', 'Increase the oral mesalazine dose further and add a topical enema, managed as an outpatient', false, 'Ruled out because increasing aminosalicylate dose is insufficient for severe disease meeting Truelove and Witts criteria; this requires inpatient IV corticosteroid therapy, not outpatient escalation of 5-ASA.', 2),
('c7000000-0000-0000-0000-000000000017', 'C', 'Arrange elective outpatient colonoscopy in 4 weeks to reassess disease extent', false, 'Ruled out because this delays urgent treatment of an acute severe flare; while colonoscopy/sigmoidoscopy may be performed cautiously to assess disease and exclude infection, definitive treatment (admission, IV steroids) should not be delayed for elective outpatient endoscopy.', 3),
('c7000000-0000-0000-0000-000000000017', 'D', 'Start oral azathioprine as monotherapy for rapid disease control', false, 'Ruled out because azathioprine has a slow onset of action (weeks to months) and is not appropriate for inducing remission in an acute severe flare; it is used as a maintenance/steroid-sparing agent, not for acute severe presentations.', 4),
('c7000000-0000-0000-0000-000000000017', 'E', 'Admit to hospital for IV corticosteroids', true, 'Correct. This patient meets Truelove and Witts criteria for a severe flare (≥6 bloody stools/day plus at least one marker of systemic toxicity — here fever, tachycardia, anaemia and raised ESR); acute severe ulcerative colitis requires hospital admission for IV corticosteroids, with close monitoring and escalation (e.g. infliximab or ciclosporin, and surgical review) if there is no adequate response within 72 hours.', 5),
('c7000000-0000-0000-0000-000000000018', 'A', 'Urology, as this is likely a urethral fistula', false, $x$Ruled out because the clinical and MRI findings describe a perianal (anorectal) fistula related to Crohn's disease, not a urological problem; urology involvement is not the appropriate initial referral here.$x$, 1),
('c7000000-0000-0000-0000-000000000018', 'B', 'Dermatology, for management of a skin abscess', false, $x$Ruled out because this is a fistulising complication of transmural Crohn's disease requiring surgical and gastroenterological input, not a primary dermatological skin condition.$x$, 2),
('c7000000-0000-0000-0000-000000000018', 'C', 'Discharge with oral antibiotics only and no specialist referral', false, $x$Ruled out because perianal fistulising Crohn's disease is a complex, often relapsing complication requiring specialist multidisciplinary management (colorectal surgery and gastroenterology), not antibiotics alone without follow-up.$x$, 3),
('c7000000-0000-0000-0000-000000000018', 'D', $x$Colorectal surgery, in conjunction with ongoing gastroenterology management of the underlying Crohn's disease$x$, true, $x$Correct. Perianal fistulising Crohn's disease requires combined management: colorectal surgical assessment (often with examination under anaesthesia and seton placement to control sepsis) alongside gastroenterology-led medical therapy (commonly anti-TNF agents such as infliximab), as neither specialty alone adequately addresses both the structural and inflammatory components.$x$, 4),
('c7000000-0000-0000-0000-000000000018', 'E', 'Palliative care referral for symptom management only', false, $x$Ruled out because this is a manageable complication of Crohn's disease with active treatment options (surgical drainage/seton, anti-TNF therapy) rather than an end-of-life or purely palliative issue.$x$, 5),
('c7000000-0000-0000-0000-000000000019', 'A', 'Withhold azathioprine and arrange urgent repeat full blood count with clinical review', true, 'Correct. A significant fall in white cell count in a patient on azathioprine indicates bone marrow suppression, a recognised and potentially serious adverse effect of thiopurines; the drug should be withheld and the blood count urgently rechecked with clinical assessment before deciding on dose adjustment or discontinuation, to avoid progression to severe neutropenia and risk of infection.', 1),
('c7000000-0000-0000-0000-000000000019', 'B', 'Continue azathioprine at the same dose and recheck bloods in 3 months as per routine monitoring', false, 'Ruled out because a new significant drop in white cell count requires prompt action, not continuation at the same dose with delayed routine monitoring, given the risk of worsening myelosuppression and infection.', 2),
('c7000000-0000-0000-0000-000000000019', 'C', 'Increase the azathioprine dose to improve disease control', false, 'Ruled out because increasing the dose in the context of falling white cell count would worsen bone marrow suppression and is dangerous.', 3),
('c7000000-0000-0000-0000-000000000019', 'D', 'Switch immediately to infliximab without addressing the abnormal blood count first', false, 'Ruled out because the immediate priority is to address the potentially dangerous cytopenia (withhold the causative drug, recheck bloods) before considering alternative therapy; safety comes first.', 4),
('c7000000-0000-0000-0000-000000000019', 'E', 'Reassure the patient that fatigue is an expected side effect requiring no action', false, 'Ruled out because a significant leucopenia is a laboratory abnormality requiring action, not something to be dismissed as an expected, inconsequential side effect.', 5),
('c7000000-0000-0000-0000-000000000020', 'A', 'Switch to long-term maintenance oral prednisolone', false, 'Ruled out because long-term corticosteroids are not used for maintenance therapy due to significant cumulative side effects (osteoporosis, adrenal suppression, diabetes, etc.); steroids are reserved for inducing remission in flares, with steroid-sparing agents used for maintenance.', 1),
('c7000000-0000-0000-0000-000000000020', 'B', 'Continue oral and/or topical 5-aminosalicylate (mesalazine) therapy', true, 'Correct. 5-aminosalicylates are first-line maintenance therapy for mild-to-moderate ulcerative colitis to sustain remission and reduce relapse risk, and are also associated with a reduction in long-term colorectal cancer risk in UC; topical therapy is particularly effective for left-sided/distal disease, often combined with oral treatment.', 2),
('c7000000-0000-0000-0000-000000000020', 'C', 'Stop all treatment now that he is in remission', false, 'Ruled out because stopping maintenance therapy in UC significantly increases the risk of relapse; ongoing maintenance treatment is recommended even during remission.', 3),
('c7000000-0000-0000-0000-000000000020', 'D', 'Start biologic therapy (e.g. infliximab) as first-line maintenance for his currently well-controlled disease', false, 'Ruled out because biologics are generally reserved for moderate-to-severe disease or those who fail conventional therapy (5-ASA, thiopurines), not as first-line maintenance in a patient already stable and well controlled.', 4),
('c7000000-0000-0000-0000-000000000020', 'E', 'Perform an elective colectomy to eliminate cancer risk', false, 'Ruled out because surgery is not indicated for well-controlled disease in remission; it is reserved for medically refractory disease, complications, or dysplasia/cancer found on surveillance, not as a routine risk-reduction strategy in stable disease.', 5),
('c7000000-0000-0000-0000-000000000021', 'A', 'Pyoderma gangrenosum', false, 'Ruled out because pyoderma gangrenosum typically presents as a painful lesion that progresses to ulceration with a violaceous undermined border, rather than the non-ulcerating erythematous nodules described here.', 1),
('c7000000-0000-0000-0000-000000000021', 'B', 'Cellulitis', false, 'Ruled out because there is no fever or spreading erythema with systemic infective features described, and the clear temporal association with a bowel flare (a classic IBD-associated skin finding) points to erythema nodosum rather than infection.', 2),
('c7000000-0000-0000-0000-000000000021', 'C', 'Psoriasis', false, 'Ruled out because psoriasis presents with well-demarcated scaly plaques, typically on extensor surfaces, rather than tender erythematous nodules coinciding with a bowel flare.', 3),
('c7000000-0000-0000-0000-000000000021', 'D', 'Deep vein thrombosis', false, 'Ruled out because DVT typically presents as unilateral leg swelling and pain rather than bilateral tender erythematous nodules, and does not typically parallel bowel disease activity in this way.', 4),
('c7000000-0000-0000-0000-000000000021', 'E', $x$Erythema nodosum, as an extraintestinal manifestation of active Crohn's disease$x$, true, 'Correct. Tender, erythematous, non-ulcerating nodules on the shins developing alongside a flare of underlying IBD is characteristic of erythema nodosum, a recognised extraintestinal manifestation that typically parallels disease activity and improves as the underlying bowel inflammation is treated.', 5),
('c7000000-0000-0000-0000-000000000022', 'A', 'Viral hepatitis A infection', false, 'Ruled out because hepatitis A typically causes a marked rise in ALT often exceeding AST (rather than the AST-predominant pattern seen here) and is usually associated with a history of faecal-oral exposure rather than a recent increase in alcohol intake.', 1),
('c7000000-0000-0000-0000-000000000022', 'B', 'Primary biliary cholangitis', false, 'Ruled out because this typically presents in middle-aged women with pruritus and a cholestatic pattern (raised ALP, anti-mitochondrial antibodies), not the acute AST-predominant hepatitic picture following an alcohol binge described here.', 2),
('c7000000-0000-0000-0000-000000000022', 'C', 'Alcoholic hepatitis', true, 'Correct. A history of a recent increase in alcohol intake with jaundice, fever, tender hepatomegaly, and a disproportionately raised AST relative to ALT (AST:ALT ratio typically >2) with raised GGT is characteristic of alcoholic hepatitis, an acute inflammatory liver injury from alcohol.', 3),
('c7000000-0000-0000-0000-000000000022', 'D', 'Autoimmune hepatitis', false, 'Ruled out because although this can cause an acute hepatitic picture, the clear temporal relationship to increased alcohol intake and the classic AST:ALT ratio pattern make alcoholic hepatitis far more likely in this context.', 4),
('c7000000-0000-0000-0000-000000000022', 'E', 'Gallstone-related acute cholecystitis', false, 'Ruled out because although right upper quadrant pain can occur in cholecystitis, the pattern of markedly deranged transaminases with an AST-predominant pattern and the alcohol history is more consistent with alcoholic hepatitis; cholecystitis typically shows a more cholestatic/inflammatory pattern with imaging findings of gallbladder wall thickening.', 5),
('c7000000-0000-0000-0000-000000000023', 'A', 'Immediate large-volume paracentesis without diuretic therapy or albumin cover', false, 'Ruled out because although large-volume paracentesis is used for tense/refractory ascites (with albumin replacement to reduce the risk of paracentesis-induced circulatory dysfunction), first-line management of new or uncomplicated ascites is dietary sodium restriction and diuretics; paracentesis alone without addressing the underlying fluid retention is not the first-line approach here.', 1),
('c7000000-0000-0000-0000-000000000023', 'B', 'Dietary sodium restriction and spironolactone (with furosemide added if needed)', true, 'Correct. Uncomplicated cirrhotic ascites (confirmed here by a high serum-ascites albumin gradient consistent with portal hypertension, and a neutrophil count below the threshold for spontaneous bacterial peritonitis) is managed first-line with sodium restriction and diuretics, typically starting with an aldosterone antagonist (spironolactone), adding a loop diuretic (furosemide) if the response is inadequate.', 2),
('c7000000-0000-0000-0000-000000000023', 'C', 'Start empirical IV antibiotics for spontaneous bacterial peritonitis', false, 'Ruled out because the ascitic fluid neutrophil count is below the diagnostic threshold for SBP (typically ≥250 cells/microlitre), so empirical antibiotics for SBP are not indicated based on this result.', 3),
('c7000000-0000-0000-0000-000000000023', 'D', 'Fluid restriction alone, without sodium restriction or diuretics', false, 'Ruled out because fluid restriction is generally reserved for significant hyponatraemia in cirrhosis, not as first-line management of ascites itself; sodium restriction and diuretics are the mainstay of initial treatment.', 4),
('c7000000-0000-0000-0000-000000000023', 'E', 'Insert a transjugular intrahepatic portosystemic shunt (TIPS) immediately', false, 'Ruled out because TIPS is reserved for refractory ascites not responding to diuretics and paracentesis, not as an initial treatment for new ascites.', 5),
('c7000000-0000-0000-0000-000000000024', 'A', 'Oral lactulose, titrated to achieve 2-3 soft stools per day', true, 'Correct. Confusion and asterixis in a patient with cirrhosis, precipitated here by constipation (a common precipitant, along with infection, GI bleeding, and medication non-adherence), is characteristic of hepatic encephalopathy; first-line treatment is lactulose, which reduces colonic ammonia production and absorption by increasing gut transit and altering colonic pH.', 1),
('c7000000-0000-0000-0000-000000000024', 'B', 'Intravenous mannitol', false, 'Ruled out because mannitol is used to reduce intracranial pressure/cerebral oedema in conditions like acute liver failure with raised ICP, not as first-line treatment for hepatic encephalopathy in chronic cirrhosis.', 2),
('c7000000-0000-0000-0000-000000000024', 'C', 'High-protein diet to correct malnutrition', false, 'Ruled out because although adequate nutrition is important in cirrhosis, protein restriction is not first-line, but a very high-protein intake during an acute encephalopathy episode is not the priority; the immediate treatment is directed at reducing ammonia (lactulose) and correcting precipitants.', 3),
('c7000000-0000-0000-0000-000000000024', 'D', 'Immediate liver transplantation assessment as the only effective treatment', false, 'Ruled out because although recurrent or refractory encephalopathy may eventually prompt transplant assessment, the immediate management of this acute episode is medical (lactulose, treating precipitants), not emergency transplantation.', 4),
('c7000000-0000-0000-0000-000000000024', 'E', 'Sedation with benzodiazepines to manage his agitation', false, 'Ruled out because benzodiazepines can worsen hepatic encephalopathy and should generally be avoided in cirrhotic patients with confusion; they are not the treatment for the underlying cause.', 5),
('c7000000-0000-0000-0000-000000000025', 'A', 'Withhold antibiotics until ascitic fluid culture results are available in 48-72 hours', false, 'Ruled out because SBP is a medical emergency with significant mortality if untreated; empirical antibiotics must be started immediately based on the neutrophil count, not delayed pending culture, which may also be falsely negative in a proportion of cases.', 1),
('c7000000-0000-0000-0000-000000000025', 'B', 'Perform large-volume paracentesis as the sole treatment, without antibiotics', false, 'Ruled out because paracentesis alone does not treat the underlying infection; antibiotics are essential, and repeat large-volume paracentesis is not the primary treatment for SBP.', 2),
('c7000000-0000-0000-0000-000000000025', 'C', 'Start oral antifungal therapy for suspected fungal peritonitis', false, 'Ruled out because SBP is overwhelmingly bacterial (commonly E. coli, Klebsiella, and Streptococcus/Enterococcus species), and empirical treatment targets bacterial pathogens, not fungi, unless there is a specific reason to suspect fungal infection.', 3),
('c7000000-0000-0000-0000-000000000025', 'D', 'Start empirical IV antibiotics (e.g. a third-generation cephalosporin) without waiting for culture results', true, 'Correct. An ascitic fluid neutrophil count ≥250 cells/microlitre in a cirrhotic patient with fever, abdominal pain and worsening confusion confirms spontaneous bacterial peritonitis, a life-threatening infection requiring prompt empirical IV antibiotic therapy (typically a third-generation cephalosporin) without delay for culture results, alongside consideration of IV albumin in those with renal impairment to reduce risk of hepatorenal syndrome.', 4),
('c7000000-0000-0000-0000-000000000025', 'E', 'Discharge home with oral antibiotics and outpatient review in one week', false, 'Ruled out because SBP in a haemodynamically compromised, confused patient requires inpatient management with IV antibiotics and close monitoring, not outpatient treatment.', 5),
('c7000000-0000-0000-0000-000000000026', 'A', 'Repeat endoscopic band ligation for a third time and no further escalation', false, 'Ruled out because with recurrent bleeding despite adequate endoscopic attempts and haemodynamic instability, escalation to balloon tamponade/TIPS is indicated rather than repeating the same failed approach indefinitely.', 1),
('c7000000-0000-0000-0000-000000000026', 'B', 'Discontinue terlipressin and antibiotics as they have not stopped the bleeding', false, 'Ruled out because these should generally be continued as part of ongoing supportive management of variceal bleeding while escalating definitive treatment, not stopped due to perceived failure of a single measure.', 2),
('c7000000-0000-0000-0000-000000000026', 'C', 'Discharge for outpatient hepatology follow-up once haemodynamically stable enough to mobilise', false, 'Ruled out because this is an unstable, uncontrolled variceal haemorrhage requiring urgent escalation of inpatient treatment, not outpatient management.', 3),
('c7000000-0000-0000-0000-000000000026', 'D', 'Perform an elective liver transplant assessment as the immediate next step', false, 'Ruled out because although transplantation may be considered in the longer term for decompensated cirrhosis, the immediate priority is controlling the acute life-threatening haemorrhage with tamponade/TIPS, not initiating transplant assessment as the next step.', 4),
('c7000000-0000-0000-0000-000000000026', 'E', 'Balloon tamponade as a temporary measure while arranging transjugular intrahepatic portosystemic shunt (TIPS)', true, 'Correct. When variceal bleeding is uncontrolled or recurs despite two attempts at endoscopic therapy, balloon tamponade (e.g. Sengstaken-Blakemore tube) can be used as a temporary bridge to control bleeding, while definitive treatment with TIPS is arranged to achieve durable haemostasis by decompressing the portal system.', 5),
('c7000000-0000-0000-0000-000000000027', 'A', 'Reassure and discharge as she currently feels well with normal observations', false, 'Ruled out because feeling well and having normal observations early after paracetamol overdose does not exclude significant hepatotoxicity risk, which develops later; treatment is guided by the paracetamol level relative to the nomogram, which here indicates treatment is required.', 1),
('c7000000-0000-0000-0000-000000000027', 'B', 'Perform gastric lavage as the definitive treatment', false, 'Ruled out because gastric lavage is not standard management for paracetamol overdose; activated charcoal (if within 1 hour of ingestion) and N-acetylcysteine based on levels are the mainstays of treatment.', 2),
('c7000000-0000-0000-0000-000000000027', 'C', 'Administer activated charcoal only, without N-acetylcysteine, as she presented outside the 1-hour window', false, 'Ruled out because although charcoal is most effective within 1 hour of ingestion (and so is less useful now at 6 hours), N-acetylcysteine is indicated based on her paracetamol level being above the treatment line, regardless of the charcoal window having passed.', 3),
('c7000000-0000-0000-0000-000000000027', 'D', 'Start intravenous N-acetylcysteine according to local protocol', true, 'Correct. A paracetamol level above the treatment line on the nomogram after a significant staggered or acute overdose indicates a risk of hepatotoxicity, and IV N-acetylcysteine should be started promptly to replenish glutathione and prevent liver injury, ideally within 8 hours of ingestion for maximal efficacy though it is still given if this window has passed.', 4),
('c7000000-0000-0000-0000-000000000027', 'E', 'Delay treatment until liver function tests become abnormal', false, 'Ruled out because treatment with N-acetylcysteine should be started based on the paracetamol level relative to the treatment nomogram, without waiting for liver function derangement to develop, as earlier treatment is more effective at preventing hepatotoxicity.', 5),
('c7000000-0000-0000-0000-000000000028', 'A', $x$Wilson's disease$x$, false, $x$Ruled out because Wilson's disease is a disorder of copper accumulation typically presenting with neuropsychiatric features and Kayser-Fleuring rings, with low serum caeruloplasmin, not the iron overload pattern (raised ferritin and transferrin saturation) and bronze pigmentation described here.$x$, 1),
('c7000000-0000-0000-0000-000000000028', 'B', 'Alpha-1 antitrypsin deficiency', false, 'Ruled out because this typically presents with early-onset emphysema and/or liver disease due to abnormal protein accumulation, not the iron overload markers and skin/joint/endocrine features described.', 2),
('c7000000-0000-0000-0000-000000000028', 'C', 'Hereditary haemochromatosis', true, $x$Correct. The combination of fatigue, bronze skin pigmentation, arthropathy of the small joints of the hands, new-onset diabetes ('bronze diabetes'), raised transaminases, markedly elevated ferritin with high transferrin saturation, and a positive family history is classic for hereditary haemochromatosis, an autosomal recessive disorder of iron overload most commonly due to HFE gene mutations.$x$, 3),
('c7000000-0000-0000-0000-000000000028', 'D', 'Primary biliary cholangitis', false, 'Ruled out because this typically presents in middle-aged women with pruritus and a cholestatic LFT pattern with positive anti-mitochondrial antibodies, not iron overload with bronze skin pigmentation and diabetes.', 4),
('c7000000-0000-0000-0000-000000000028', 'E', 'Non-alcoholic fatty liver disease', false, 'Ruled out because although this is common and associated with diabetes, it does not explain the bronze skin pigmentation, arthropathy, markedly raised ferritin and transferrin saturation, or the family history pattern described, which are specific to haemochromatosis.', 5),
('c7000000-0000-0000-0000-000000000029', 'A', 'Start a gluten-free diet immediately without further testing', false, 'Ruled out because starting a gluten-free diet before biopsy would normalise the mucosal changes and make histological confirmation difficult or impossible; biopsy confirmation should occur while gluten is still being consumed.', 1),
('c7000000-0000-0000-0000-000000000029', 'B', 'Upper GI endoscopy with duodenal biopsies while continuing a gluten-containing diet', true, 'Correct. A strongly positive anti-tTG IgA in a patient with symptoms and iron-deficiency anaemia is highly suggestive of coeliac disease, but duodenal biopsy (showing villous atrophy, crypt hyperplasia and intraepithelial lymphocytosis) while the patient continues eating gluten is required to confirm the diagnosis in adults before committing to lifelong dietary restriction.', 2),
('c7000000-0000-0000-0000-000000000029', 'C', 'Faecal calprotectin', false, 'Ruled out because this is a marker of intestinal inflammation used mainly to help distinguish IBD from IBS, not to confirm coeliac disease, which requires antibody testing and duodenal biopsy.', 3),
('c7000000-0000-0000-0000-000000000029', 'D', 'Abdominal ultrasound', false, 'Ruled out because this does not have a role in diagnosing coeliac disease, which is a small bowel mucosal condition assessed by biopsy rather than imaging.', 4),
('c7000000-0000-0000-0000-000000000029', 'E', 'Hydrogen breath test for lactose intolerance', false, 'Ruled out because although lactose intolerance can coexist with or mimic some coeliac symptoms, the strongly positive coeliac serology points to coeliac disease as the primary concern, which requires biopsy confirmation, not a breath test.', 5),
('c7000000-0000-0000-0000-000000000030', 'A', 'Pernicious anaemia due to autoimmune gastric parietal cell/intrinsic factor antibody-mediated destruction', true, 'Correct. Macrocytic anaemia with neurological features (peripheral neuropathy) and glossitis in a patient with a normal diet and a background of another autoimmune condition (autoimmune thyroid disease often coexists with pernicious anaemia) points to pernicious anaemia, caused by autoimmune destruction of gastric parietal cells leading to loss of intrinsic factor and impaired B12 absorption in the terminal ileum.', 1),
('c7000000-0000-0000-0000-000000000030', 'B', 'Dietary B12 deficiency due to a vegan diet', false, 'Ruled out because she reports eating meat regularly with no dietary restriction, making a purely dietary cause unlikely; an absorptive cause (pernicious anaemia) is far more consistent with her history.', 2),
('c7000000-0000-0000-0000-000000000030', 'C', 'Coeliac disease affecting the terminal ileum', false, 'Ruled out because coeliac disease primarily affects the proximal small bowel (duodenum/jejunum) causing iron and folate deficiency more than B12 deficiency, which is absorbed in the terminal ileum; the clinical picture here (autoimmune thyroid disease, no GI symptoms mentioned) is more consistent with pernicious anaemia.', 3),
('c7000000-0000-0000-0000-000000000030', 'D', 'Chronic pancreatitis with exocrine insufficiency', false, 'Ruled out because although pancreatic insufficiency can rarely contribute to B12 malabsorption, there is no history suggestive of pancreatitis (e.g. steatorrhoea, alcohol history, abdominal pain), and the autoimmune association makes pernicious anaemia far more likely.', 4),
('c7000000-0000-0000-0000-000000000030', 'E', 'Long-term proton pump inhibitor use reducing B12 absorption', false, 'Ruled out because there is no mention of PPI use in this history, and the clinical picture with coexisting autoimmune thyroid disease strongly favours pernicious anaemia as the underlying cause.', 5),
('c7000000-0000-0000-0000-000000000031', 'A', 'Start oral iron replacement and reassure with no further investigation needed', false, 'Ruled out because iron-deficiency anaemia without an obvious cause requires investigation to exclude an underlying gastrointestinal malignancy or other pathology; iron replacement alone without seeking the cause risks missing a serious diagnosis such as colorectal cancer.', 1),
('c7000000-0000-0000-0000-000000000031', 'B', 'Urgent referral for investigation of the gastrointestinal tract, including colonoscopy, to identify a source of occult blood loss', true, 'Correct. Unexplained iron-deficiency anaemia in an adult, particularly a man or postmenopausal woman without an obvious cause, should be investigated urgently to identify an occult gastrointestinal source of blood loss, including colorectal cancer, even in the absence of overt bleeding or classic red flag symptoms, per UK 2-week-wait referral guidance.', 2),
('c7000000-0000-0000-0000-000000000031', 'C', 'Arrange coeliac serology only, with no further investigation if negative', false, 'Ruled out because although coeliac disease is a recognised cause of iron deficiency and should be tested for, it does not exclude the need to also investigate for a gastrointestinal source of blood loss such as colorectal cancer, particularly in a man of this age.', 3),
('c7000000-0000-0000-0000-000000000031', 'D', 'Reassure that this is likely due to normal ageing and no further action is required', false, 'Ruled out because unexplained iron-deficiency anaemia is never a normal ageing finding and must be actively investigated to identify the underlying cause.', 4),
('c7000000-0000-0000-0000-000000000031', 'E', 'Refer to haematology for bone marrow biopsy as the first investigation', false, 'Ruled out because bone marrow biopsy is not the first-line investigation for iron-deficiency anaemia; the priority is to identify a gastrointestinal source of blood loss with endoscopic investigation (and coeliac serology), reserving haematology referral for cases where the cause remains unclear after these are completed.', 5),
('c7000000-0000-0000-0000-000000000032', 'A', $x$Wernicke's encephalopathy$x$, false, 'Ruled out as the primary explanation for this specific electrolyte and cardiac picture; while thiamine deficiency is also a concern in malnourished patients with alcohol use disorder and should be treated prophylactically, the described combination of severe hypophosphataemia, hypokalaemia and hypomagnesaemia after starting feeding is specifically characteristic of refeeding syndrome.', 1),
('c7000000-0000-0000-0000-000000000032', 'B', 'Acute kidney injury causing electrolyte derangement', false, 'Ruled out because AKI would more typically cause hyperkalaemia and retention of phosphate (raised, not low, phosphate) rather than the profound hypophosphataemia, hypokalaemia and hypomagnesaemia seen here, which fit the pattern of refeeding syndrome.', 2),
('c7000000-0000-0000-0000-000000000032', 'C', 'Refeeding syndrome', true, 'Correct. Reintroducing nutrition after a period of prolonged poor intake or starvation (particularly in patients with chronic alcohol use) can precipitate a rapid intracellular shift of phosphate, potassium and magnesium driven by insulin release in response to feeding, causing the severe hypophosphataemia, hypokalaemia and hypomagnesaemia seen here, which can result in arrhythmias, weakness and confusion.', 3),
('c7000000-0000-0000-0000-000000000032', 'D', 'Diabetic ketoacidosis', false, 'Ruled out because there is no mention of hyperglycaemia, ketosis or acidosis; the clinical and biochemical picture (recent reintroduction of feeding after starvation, severe hypophosphataemia) is specific to refeeding syndrome.', 4),
('c7000000-0000-0000-0000-000000000032', 'E', 'Alcohol withdrawal seizures', false, 'Ruled out because although alcohol withdrawal is a relevant risk in this patient, the specific biochemical derangements described (severe hypophosphataemia, hypokalaemia, hypomagnesaemia occurring after starting feeding) are the hallmark of refeeding syndrome rather than withdrawal alone.', 5),
('c7000000-0000-0000-0000-000000000033', 'A', 'Osteomalacia secondary to vitamin D and calcium malabsorption following bariatric surgery', true, 'Correct. Bariatric surgery, particularly malabsorptive procedures like Roux-en-Y gastric bypass, significantly reduces absorption of fat-soluble vitamins (including vitamin D) and calcium; when supplementation is not maintained, this leads to osteomalacia, presenting with bone pain, proximal myopathy, low calcium and vitamin D, and secondary hyperparathyroidism (raised PTH) as the body attempts to maintain serum calcium.', 1),
('c7000000-0000-0000-0000-000000000033', 'B', 'Primary hyperparathyroidism', false, 'Ruled out because primary hyperparathyroidism typically causes hypercalcaemia with an inappropriately raised PTH, whereas here calcium is low with a raised PTH, which is a secondary (appropriate, compensatory) response to vitamin D deficiency and calcium malabsorption, i.e. osteomalacia.', 2),
('c7000000-0000-0000-0000-000000000033', 'C', $x$Paget's disease of bone$x$, false, 'Ruled out because this typically presents with localised bone pain and raised alkaline phosphatase with normal calcium, vitamin D and PTH, not the diffuse pain and biochemical picture of vitamin D deficiency described here.', 3),
('c7000000-0000-0000-0000-000000000033', 'D', 'Multiple myeloma', false, 'Ruled out because this typically presents with hypercalcaemia, renal impairment, anaemia and bone lesions, along with other features, rather than the vitamin D deficiency picture with secondary hyperparathyroidism seen here.', 4),
('c7000000-0000-0000-0000-000000000033', 'E', 'Osteoporosis alone, unrelated to her surgery', false, 'Ruled out because although reduced bone density can be seen in osteoporosis, the biochemical picture here (low calcium, low vitamin D, raised PTH) specifically indicates osteomalacia due to malabsorption, not simple age-related bone density loss.', 5),
('c7000000-0000-0000-0000-000000000034', 'A', 'Irritable bowel syndrome with diarrhoea', false, 'Ruled out because IBS is a functional disorder without structural bowel loss; his symptoms are directly explained by his extensive surgical resection and resulting anatomical short bowel, not a functional diagnosis.', 1),
('c7000000-0000-0000-0000-000000000034', 'B', 'Coeliac disease', false, 'Ruled out because there is no mention of gluten-related triggers or serology, and his clinical picture is fully explained by his known extensive bowel resection rather than a separate autoimmune enteropathy.', 2),
('c7000000-0000-0000-0000-000000000034', 'C', 'Chronic pancreatitis with exocrine insufficiency', false, 'Ruled out because there is no history suggestive of pancreatic disease (alcohol history, recurrent pancreatitis); his malabsorption and fluid losses are explained by the anatomical loss of absorptive small bowel surface area.', 3),
('c7000000-0000-0000-0000-000000000034', 'D', 'Short bowel syndrome leading to intestinal failure', true, 'Correct. Extensive small bowel resection leaving insufficient functional small bowel length results in short bowel syndrome, characterised by malabsorption of fluid, electrolytes and nutrients, causing chronic diarrhoea, dehydration, weight loss and, when severe, dependence on parenteral nutrition (intestinal failure) to maintain adequate nutrition and hydration.', 4),
('c7000000-0000-0000-0000-000000000034', 'E', 'Small intestinal bacterial overgrowth as the sole cause', false, 'Ruled out because although SIBO can complicate short bowel syndrome and contribute to symptoms, the primary underlying cause of his intestinal failure and parenteral nutrition dependence is the anatomical loss of small bowel length itself.', 5),
('c7000000-0000-0000-0000-000000000035', 'A', 'Coeliac disease', false, 'Ruled out because coeliac serology is negative and his symptoms are specifically related to dairy rather than gluten-containing foods, making lactose intolerance far more likely.', 1),
('c7000000-0000-0000-0000-000000000035', 'B', $x$Crohn's disease$x$, false, 'Ruled out because there are no systemic features, weight loss, or inflammatory markers described, and the clear, consistent dietary trigger (dairy) with symptom resolution on avoidance points to a simple food intolerance rather than inflammatory bowel disease.', 2),
('c7000000-0000-0000-0000-000000000035', 'C', 'Pancreatic exocrine insufficiency', false, 'Ruled out because this typically causes steatorrhoea (pale, greasy, foul-smelling stools) related to fat malabsorption generally, not symptoms specifically and consistently triggered by dairy products.', 3),
('c7000000-0000-0000-0000-000000000035', 'D', 'Irritable bowel syndrome unrelated to diet', false, 'Ruled out because although IBS can be diet-sensitive, the specific and consistent relationship to dairy intake with resolution on avoidance is more specific for lactose intolerance, which can be confirmed with a hydrogen breath test or trial elimination/rechallenge if needed.', 4),
('c7000000-0000-0000-0000-000000000035', 'E', 'Lactose intolerance', true, 'Correct. Symptoms of bloating, flatulence and loose stools specifically and consistently triggered by dairy products, with resolution on dairy avoidance and no red flag features or evidence of coeliac disease, is characteristic of lactose intolerance, due to relative deficiency of the enzyme lactase leading to malabsorption of lactose and its fermentation by colonic bacteria.', 5),
('c7000000-0000-0000-0000-000000000036', 'A', 'Acute pancreatitis, likely gallstone-related', true, 'Correct. Sudden severe epigastric pain radiating to the back, associated with nausea and vomiting after a fatty meal, in a patient with known gallstones, together with a markedly elevated serum lipase (more than 3 times the upper limit of normal), is diagnostic of acute pancreatitis, with gallstones being the most likely precipitant given her history.', 1),
('c7000000-0000-0000-0000-000000000036', 'B', 'Acute cholecystitis', false, $x$Ruled out because although gallstones are relevant to both conditions, cholecystitis typically causes right upper quadrant pain with a positive Murphy's sign and does not typically cause the markedly elevated lipase seen here, which is specific to pancreatic inflammation.$x$, 2),
('c7000000-0000-0000-0000-000000000036', 'C', 'Perforated peptic ulcer', false, 'Ruled out because this typically presents with sudden pain and peritonism (rigid abdomen), which is absent here, and would not explain the markedly elevated lipase, which specifically indicates pancreatic pathology.', 3),
('c7000000-0000-0000-0000-000000000036', 'D', 'Mesenteric ischaemia', false, 'Ruled out because this typically occurs in older patients with vascular risk factors, presents with pain out of proportion to examination findings, and does not classically cause a markedly elevated lipase; the gallstone history and lipase result here point clearly to pancreatitis.', 4),
('c7000000-0000-0000-0000-000000000036', 'E', 'Myocardial infarction', false, 'Ruled out because although epigastric pain can occasionally represent atypical cardiac ischaemia, the markedly elevated lipase and clear precipitant (fatty meal in a patient with known gallstones) make acute pancreatitis the clear diagnosis here.', 5),
('c7000000-0000-0000-0000-000000000037', 'A', 'Rely on serum amylase level alone at admission, as a higher amylase indicates more severe disease', false, 'Ruled out because the degree of amylase elevation does not correlate with severity of pancreatitis; amylase is useful for diagnosis but not for severity stratification, which requires validated multi-parameter scoring systems.', 1),
('c7000000-0000-0000-0000-000000000037', 'B', $x$Assess severity based solely on the patient's pain score$x$, false, 'Ruled out because pain severity is subjective and does not reliably correlate with the degree of systemic organ dysfunction or complications; objective, validated scoring systems are required.', 2),
('c7000000-0000-0000-0000-000000000037', 'C', 'Determine severity by whether the patient has vomited, with vomiting alone indicating severe disease', false, 'Ruled out because vomiting is a common symptom of pancreatitis of any severity and does not reflect systemic severity; validated scoring using physiological and biochemical parameters is required.', 3),
('c7000000-0000-0000-0000-000000000037', 'D', 'Assess severity using body mass index alone', false, 'Ruled out because although obesity is a recognised risk factor for a more severe course, BMI alone is not a validated severity scoring tool; established multi-parameter systems (e.g. Glasgow-Imrie) are used instead.', 4),
('c7000000-0000-0000-0000-000000000037', 'E', 'Use a validated scoring system such as the Glasgow-Imrie criteria (incorporating hypoxia, renal function, hypocalcaemia and inflammatory markers) at admission and 48 hours to identify severe pancreatitis requiring higher-level care', true, 'Correct. Severity assessment in acute pancreatitis is performed using validated scoring systems (e.g. Glasgow-Imrie criteria, APACHE II, or CRP trends) that incorporate features such as hypoxia, deteriorating renal function, hypocalcaemia and raised inflammatory markers; a high score at 48 hours identifies patients with severe pancreatitis who need escalation of care, often to a high-dependency or intensive care setting.', 5),
('c7000000-0000-0000-0000-000000000038', 'A', 'Acute pancreatitis alone', false, 'Ruled out because the chronicity of symptoms over years, with steatorrhoea, weight loss, new diabetes and pancreatic calcification on imaging, indicates chronic (not acute) pancreatic damage.', 1),
('c7000000-0000-0000-0000-000000000038', 'B', 'Coeliac disease', false, 'Ruled out because although this can also cause malabsorptive symptoms, the alcohol history, recurrent pain, and pancreatic calcification/ductal dilation on CT point specifically to chronic pancreatitis rather than a small bowel enteropathy.', 2),
('c7000000-0000-0000-0000-000000000038', 'C', 'Pancreatic adenocarcinoma', false, 'Ruled out because while pancreatic cancer can cause weight loss and pain, the described CT findings (calcification, ductal dilation) and long history of recurrent pain in the context of alcohol excess are classic for chronic pancreatitis rather than malignancy, though ongoing surveillance is still important as chronic pancreatitis increases cancer risk.', 3),
('c7000000-0000-0000-0000-000000000038', 'D', 'Chronic pancreatitis with exocrine (and early endocrine) insufficiency', true, 'Correct. Recurrent epigastric pain over years in a patient with a significant alcohol history, together with steatorrhoea (pancreatic exocrine insufficiency causing fat malabsorption), new hyperglycaemia (early endocrine insufficiency), and pancreatic calcification with ductal dilation on CT, is characteristic of chronic pancreatitis, most commonly caused by long-term alcohol excess in this demographic.', 4),
('c7000000-0000-0000-0000-000000000038', 'E', 'Irritable bowel syndrome', false, 'Ruled out because IBS does not cause steatorrhoea, weight loss, hyperglycaemia or pancreatic calcification; these findings indicate significant structural pancreatic pathology.', 5),
('c7000000-0000-0000-0000-000000000039', 'A', 'Biliary colic', false, 'Ruled out because biliary colic typically causes intermittent, self-limiting pain without fever or signs of inflammation on imaging (gallbladder wall thickening, pericholecystic fluid), whereas this patient has clear evidence of an inflammatory/infective process.', 1),
('c7000000-0000-0000-0000-000000000039', 'B', 'Ascending cholangitis', false, $x$Ruled out because this typically presents with Charcot's triad (fever, jaundice, RUQ pain) and is associated with common bile duct dilation/obstruction on imaging, which is specifically absent here (no CBD dilation, no mention of jaundice).$x$, 2),
('c7000000-0000-0000-0000-000000000039', 'C', 'Acute cholecystitis', true, $x$Correct. Constant right upper quadrant pain, fever, a positive Murphy's sign, and ultrasound findings of gallbladder wall thickening with pericholecystic fluid and gallstones (without common bile duct dilation) are classic for acute cholecystitis, caused by cystic duct obstruction by a gallstone leading to gallbladder inflammation.$x$, 3),
('c7000000-0000-0000-0000-000000000039', 'D', 'Acute pancreatitis', false, $x$Ruled out because the pain here is right upper quadrant with a positive Murphy's sign and gallbladder-specific ultrasound findings, rather than epigastric pain radiating to the back with elevated lipase, which would be expected in pancreatitis.$x$, 4),
('c7000000-0000-0000-0000-000000000039', 'E', 'Peptic ulcer disease', false, $x$Ruled out because the clinical (Murphy's sign, RUQ pain, fever) and ultrasound findings (gallbladder wall thickening, pericholecystic fluid, stones) are specific for acute cholecystitis rather than a peptic ulcer.$x$, 5),
('c7000000-0000-0000-0000-000000000040', 'A', 'Elective outpatient laparoscopic cholecystectomy in 6 weeks', false, 'Ruled out because this is an acute, life-threatening emergency (ascending cholangitis with signs of sepsis and altered mental status) requiring urgent inpatient biliary decompression, not elective delayed outpatient surgery.', 1),
('c7000000-0000-0000-0000-000000000040', 'B', 'Urgent biliary decompression, most commonly via ERCP', true, $x$Correct. Fever, jaundice and RUQ pain (Charcot's triad) with additional signs of sepsis and altered mental status (Reynolds' pentad, indicating suppurative cholangitis) with a dilated common bile duct and choledocholithiasis on ultrasound indicates ascending cholangitis; after initial resuscitation and IV antibiotics, urgent biliary decompression (most commonly via ERCP) is required to relieve the obstruction and drain infected bile, as this is a life-threatening emergency.$x$, 2),
('c7000000-0000-0000-0000-000000000040', 'C', 'Oral antibiotics alone with outpatient follow-up', false, 'Ruled out because this patient has signs of severe sepsis (hypotension, tachycardia, confusion) and requires inpatient IV antibiotics and urgent biliary decompression, not oral antibiotics managed as an outpatient.', 3),
('c7000000-0000-0000-0000-000000000040', 'D', 'Observation alone, as most cases of cholangitis resolve without intervention', false, 'Ruled out because ascending cholangitis with signs of sepsis and biliary obstruction requires urgent decompression in addition to antibiotics; observation alone risks deterioration and death from ongoing sepsis and obstruction.', 4),
('c7000000-0000-0000-0000-000000000040', 'E', 'Immediate open cholecystectomy as the first intervention', false, 'Ruled out because ERCP for biliary decompression is the first-line urgent intervention in ascending cholangitis; cholecystectomy (if the gallbladder is the source of stones) is typically considered later, once the acute cholangitis has been treated and the patient has stabilised.', 5),
('c7000000-0000-0000-0000-000000000041', 'A', 'Choledocholithiasis (common bile duct stones)', false, $x$Ruled out because gallstone-related biliary obstruction typically causes painful jaundice with a tender, often impalpable (contracted/fibrotic) gallbladder, not a painless presentation with a palpable non-tender gallbladder and a pancreatic head mass; Courvoisier's sign specifically suggests a malignant, non-stone cause.$x$, 1),
('c7000000-0000-0000-0000-000000000041', 'B', 'Acute cholecystitis', false, $x$Ruled out because this typically causes painful RUQ symptoms with fever and a positive Murphy's sign, not painless progressive jaundice with a pancreatic head mass and double duct sign on imaging.$x$, 2),
('c7000000-0000-0000-0000-000000000041', 'C', 'Primary sclerosing cholangitis', false, $x$Ruled out because this typically presents in younger patients, often with associated ulcerative colitis, and produces a 'beaded' appearance of the biliary tree on imaging (multifocal strictures), rather than a discrete pancreatic head mass causing double duct dilation.$x$, 3),
('c7000000-0000-0000-0000-000000000041', 'D', 'Carcinoma of the head of the pancreas', true, $x$Correct. Progressive painless obstructive jaundice with weight loss, a palpable non-tender distended gallbladder (Courvoisier's sign, suggesting a non-gallstone cause of biliary obstruction), and a mass in the pancreatic head with dilation of both the common bile duct and pancreatic duct ('double duct sign') on CT, is classic for pancreatic head carcinoma causing biliary obstruction.$x$, 4),
('c7000000-0000-0000-0000-000000000041', 'E', 'Viral hepatitis', false, 'Ruled out because this typically causes a hepatocellular (not obstructive) pattern of jaundice without a palpable gallbladder or a pancreatic mass on imaging.', 5),
('c7000000-0000-0000-0000-000000000042', 'A', 'Simple adhesional small bowel obstruction', false, 'Ruled out because the presence of pneumobilia and a calcified opacity distinct from the biliary tree specifically points to gallstone ileus rather than simple adhesions, for which there is also no relevant surgical history described.', 1),
('c7000000-0000-0000-0000-000000000042', 'B', 'Acute cholecystitis alone', false, 'Ruled out because although gallstones and cholecystitis-related inflammation can lead to fistula formation over time, the current presentation with small bowel obstruction and radiological evidence of an ectopic gallstone indicates gallstone ileus rather than isolated cholecystitis.', 2),
('c7000000-0000-0000-0000-000000000042', 'C', 'Gallstone ileus', true, $x$Correct. Small bowel obstruction in an elderly patient with known gallstones, together with pneumobilia (indicating a cholecysto-enteric fistula allowing air to enter the biliary tree) and a calcified opacity in the bowel distinct from the gallbladder/biliary tree (representing the impacted gallstone, often at the terminal ileum), is the classic triad (Rigler's triad) for gallstone ileus, a mechanical bowel obstruction caused by a large gallstone that has eroded through a biliary-enteric fistula and become impacted in the bowel.$x$, 3),
('c7000000-0000-0000-0000-000000000042', 'D', 'Sigmoid volvulus', false, 'Ruled out because this causes large bowel obstruction with a characteristic radiological appearance (e.g. coffee bean sign), not the small bowel dilation with pneumobilia and ectopic calcified gallstone described here.', 4),
('c7000000-0000-0000-0000-000000000042', 'E', 'Choledocholithiasis with biliary colic', false, 'Ruled out because this would cause biliary-type pain and possibly jaundice, not small bowel obstruction with pneumobilia and an ectopic stone in the bowel lumen away from the biliary tree.', 5),
('c7000000-0000-0000-0000-000000000043', 'A', 'Urgent upper GI endoscopy before starting any treatment', false, 'Ruled out because there are no red flag features (dysphagia, weight loss, anaemia, age-related risk) requiring urgent endoscopy; empirical treatment is appropriate first-line management for typical reflux symptoms.', 1),
('c7000000-0000-0000-0000-000000000043', 'B', 'Start a H2 receptor antagonist as first-line therapy in preference to a PPI', false, 'Ruled out because proton pump inhibitors are more effective and are recommended as first-line pharmacological therapy for GORD; H2 antagonists are typically used as an alternative or add-on if PPIs are insufficient.', 2),
('c7000000-0000-0000-0000-000000000043', 'C', 'Refer for anti-reflux surgery (fundoplication) as first-line treatment', false, 'Ruled out because surgery is reserved for patients with confirmed GORD who have an inadequate response to or cannot tolerate medical therapy, not as an initial treatment approach.', 3),
('c7000000-0000-0000-0000-000000000043', 'D', 'Advise no treatment is required as symptoms will resolve spontaneously', false, 'Ruled out because although lifestyle and medical treatment are often effective, no action at all is not an appropriate response to significant, persistent symptoms affecting quality of life.', 4),
('c7000000-0000-0000-0000-000000000043', 'E', 'Lifestyle advice (weight loss, smaller meals, avoiding late meals, raising the head of the bed) alongside a trial of a proton pump inhibitor', true, 'Correct. Classic symptoms of gastro-oesophageal reflux disease without red flag features can be managed empirically in primary care with lifestyle modification and a trial of a proton pump inhibitor, without the need for initial endoscopy.', 5),
('c7000000-0000-0000-0000-000000000044', 'A', 'Long-term single-agent PPI therapy without addressing H. pylori', false, 'Ruled out because although PPI therapy helps symptom control and healing, it does not eradicate H. pylori, which is the underlying cause and, if untreated, predisposes to ulcer recurrence and complications; eradication therapy is required.', 1),
('c7000000-0000-0000-0000-000000000044', 'B', 'H. pylori eradication therapy (a proton pump inhibitor plus two antibiotics)', true, 'Correct. Epigastric pain suggestive of duodenal ulcer disease (relieved by eating, worse at night/a few hours after meals) with confirmed H. pylori infection should be treated with eradication therapy, typically a PPI combined with two antibiotics (commonly amoxicillin and clarithromycin or metronidazole, per local protocols), which resolves the underlying cause and promotes ulcer healing.', 2),
('c7000000-0000-0000-0000-000000000044', 'C', 'Urgent surgical referral for gastrectomy', false, 'Ruled out because uncomplicated peptic ulcer disease is managed medically with eradication therapy; surgery is reserved for complications (perforation, bleeding not controlled endoscopically, or malignancy) not for straightforward H. pylori-positive ulcer disease.', 3),
('c7000000-0000-0000-0000-000000000044', 'D', 'Reassure and advise no treatment is needed as symptoms are mild', false, 'Ruled out because confirmed H. pylori infection with symptoms suggestive of peptic ulcer disease should be treated to eradicate the infection and prevent complications such as bleeding or perforation.', 4),
('c7000000-0000-0000-0000-000000000044', 'E', 'Start high-dose aspirin for symptom relief', false, 'Ruled out because aspirin and other NSAIDs are a major cause of peptic ulcer disease and would worsen, not treat, his condition.', 5),
('c7000000-0000-0000-0000-000000000045', 'A', $x$Continue PPI therapy and arrange regular endoscopic surveillance according to local Barrett's oesophagus guidelines$x$, true, $x$Correct. Barrett's oesophagus (columnar-lined epithelium with intestinal metaplasia on biopsy) without dysplasia requires ongoing PPI therapy for reflux control and regular endoscopic surveillance (typically every 2-3 years, depending on segment length) to detect progression to dysplasia or early adenocarcinoma at a treatable stage, given its recognised premalignant potential.$x$, 1),
('c7000000-0000-0000-0000-000000000045', 'B', 'No further follow-up is needed as there is no dysplasia present', false, $x$Ruled out because although the absence of dysplasia is reassuring, Barrett's oesophagus still carries an increased risk of progression to oesophageal adenocarcinoma over time and requires ongoing surveillance, not discharge from follow-up.$x$, 2),
('c7000000-0000-0000-0000-000000000045', 'C', 'Proceed immediately to oesophagectomy', false, $x$Ruled out because surgery is not indicated for non-dysplastic Barrett's oesophagus; it is reserved for high-grade dysplasia or early cancer not amenable to endoscopic therapy.$x$, 3),
('c7000000-0000-0000-0000-000000000045', 'D', 'Stop PPI therapy as it is no longer needed', false, $x$Ruled out because ongoing acid suppression with a PPI is important to control reflux and reduce the risk of ongoing mucosal injury in Barrett's oesophagus.$x$, 4),
('c7000000-0000-0000-0000-000000000045', 'E', $x$Perform radiofrequency ablation immediately given the diagnosis of Barrett's oesophagus$x$, false, $x$Ruled out because endoscopic ablative therapy is generally reserved for confirmed dysplasia (particularly high-grade) rather than non-dysplastic Barrett's oesophagus, which is managed with surveillance.$x$, 5),
('c7000000-0000-0000-0000-000000000046', 'A', 'Proceed directly to oesophagectomy without any staging investigations', false, 'Ruled out because surgery without staging risks either operating on a patient with unresectable/metastatic disease (unnecessary morbidity) or missing more appropriate treatment planning; staging must precede definitive treatment decisions.', 1),
('c7000000-0000-0000-0000-000000000046', 'B', 'Reassure the patient that this is likely a benign stricture requiring only dilation', false, 'Ruled out because biopsy has already confirmed squamous cell carcinoma; this is a malignant diagnosis requiring oncological staging and management, not simple dilation for a benign stricture.', 2),
('c7000000-0000-0000-0000-000000000046', 'C', 'Discharge back to the GP for community management of dysphagia', false, 'Ruled out because a confirmed diagnosis of oesophageal cancer requires specialist secondary/tertiary care management (staging, MDT discussion, oncological/surgical treatment planning), not primary care management alone.', 3),
('c7000000-0000-0000-0000-000000000046', 'D', 'Start palliative chemotherapy immediately without staging', false, 'Ruled out because treatment intent (curative versus palliative) and the specific treatment plan depend on accurate staging; this should not be bypassed before starting any oncological treatment.', 4),
('c7000000-0000-0000-0000-000000000046', 'E', 'Staging investigations (e.g. CT chest/abdomen/pelvis and endoscopic ultrasound, +/- PET-CT) followed by discussion at a specialist upper GI multidisciplinary team meeting', true, 'Correct. Once a diagnosis of oesophageal cancer is confirmed histologically, the next essential step is staging (to assess local invasion, nodal involvement and distant metastases) using cross-sectional imaging, endoscopic ultrasound and/or PET-CT as appropriate, followed by discussion at a specialist MDT to plan treatment (which may be curative surgery/chemoradiotherapy or palliative depending on stage).', 5),
('c7000000-0000-0000-0000-000000000047', 'A', 'Start a proton pump inhibitor alone and review symptoms in 3 months', false, 'Ruled out because a confirmed cancer diagnosis requires prompt oncological staging and specialist management, not simple symptomatic treatment with delayed review.', 1),
('c7000000-0000-0000-0000-000000000047', 'B', 'Refer for staging investigations and discussion at a specialist upper GI multidisciplinary team meeting', true, 'Correct. Following histological confirmation of gastric adenocarcinoma, staging (typically CT chest/abdomen/pelvis, sometimes with staging laparoscopy to detect peritoneal disease) is required before treatment planning, with subsequent discussion at a specialist upper GI MDT to determine the most appropriate management (which may include surgery, perioperative chemotherapy, or palliative treatment depending on stage).', 2),
('c7000000-0000-0000-0000-000000000047', 'C', 'Reassure the patient that this represents a benign gastric ulcer', false, 'Ruled out because biopsy has already confirmed adenocarcinoma; this is a malignant diagnosis, not a benign ulcer, and requires appropriate oncological work-up.', 3),
('c7000000-0000-0000-0000-000000000047', 'D', 'Advise dietary modification only, with no further specialist referral', false, 'Ruled out because a confirmed malignancy requires specialist staging and multidisciplinary management, not dietary advice alone.', 4),
('c7000000-0000-0000-0000-000000000047', 'E', 'Arrange annual surveillance endoscopy without further action', false, 'Ruled out because gastric adenocarcinoma has already been diagnosed; surveillance endoscopy alone without staging and treatment planning would leave the cancer untreated.', 5),
('c7000000-0000-0000-0000-000000000048', 'A', 'Simple H. pylori-negative peptic ulcer disease', false, 'Ruled out because the markedly elevated and paradoxically rising gastrin level on secretin testing is diagnostic of a gastrin-secreting tumour, not simple ulcer disease unrelated to a hormonal cause.', 1),
('c7000000-0000-0000-0000-000000000048', 'B', 'Chronic pancreatitis', false, 'Ruled out because this does not classically cause markedly elevated gastrin levels or a paradoxical rise on secretin testing; the biochemical findings here are specific for a gastrinoma.', 2),
('c7000000-0000-0000-0000-000000000048', 'C', 'Zollinger-Ellison syndrome (gastrinoma)', true, 'Correct. Recurrent, multiple or refractory peptic ulcers despite adequate H. pylori eradication and acid suppression, together with diarrhoea (from excess gastric acid overwhelming pancreatic bicarbonate and damaging the small bowel mucosa) and a markedly elevated fasting gastrin that paradoxically rises further after secretin administration, is characteristic of Zollinger-Ellison syndrome, caused by a gastrin-secreting neuroendocrine tumour (gastrinoma), usually located in the duodenum or pancreas.', 3),
('c7000000-0000-0000-0000-000000000048', 'D', 'Coeliac disease', false, 'Ruled out because although this can cause diarrhoea, it does not explain recurrent multiple peptic ulcers or the markedly elevated, paradoxically rising gastrin level, which is specific to Zollinger-Ellison syndrome.', 4),
('c7000000-0000-0000-0000-000000000048', 'E', 'Irritable bowel syndrome', false, 'Ruled out because IBS does not cause recurrent peptic ulceration or abnormal gastrin physiology; this presentation reflects a specific hormonally active tumour.', 5),
('c7000000-0000-0000-0000-000000000049', 'A', 'Mallory-Weiss tear', true, 'Correct. A history of forceful repeated vomiting or retching (often after alcohol excess) followed by haematemesis, with endoscopy showing a longitudinal mucosal tear at the gastro-oesophageal junction, is characteristic of a Mallory-Weiss tear, caused by a sudden rise in intra-abdominal/intraluminal pressure during vomiting.', 1),
('c7000000-0000-0000-0000-000000000049', 'B', 'Oesophageal variceal bleeding', false, 'Ruled out because there is no history or examination evidence of chronic liver disease or portal hypertension, and endoscopy specifically shows a mucosal tear rather than dilated varices.', 2),
('c7000000-0000-0000-0000-000000000049', 'C', 'Boerhaave syndrome (oesophageal rupture)', false, 'Ruled out because this represents a full-thickness oesophageal perforation typically causing severe chest pain, subcutaneous emphysema and systemic illness/sepsis, which is a much more severe and different presentation from the small mucosal tear with a haemodynamically stable patient described here.', 3),
('c7000000-0000-0000-0000-000000000049', 'D', 'Peptic ulcer disease', false, 'Ruled out because endoscopy specifically identified a mucosal tear at the gastro-oesophageal junction related to vomiting, not an ulcer elsewhere in the stomach or duodenum.', 4),
('c7000000-0000-0000-0000-000000000049', 'E', 'Oesophageal candidiasis', false, 'Ruled out because this typically presents with odynophagia in immunocompromised patients and shows white plaques on endoscopy, not a mucosal tear related to vomiting.', 5),
('c7000000-0000-0000-0000-000000000050', 'A', 'Refer urgently for endoscopy under the 2-week-wait pathway regardless of symptoms', false, 'Ruled out because urgent 2-week-wait referral is reserved for patients with red flag features (e.g. dysphagia, weight loss, GI bleeding, unexplained iron-deficiency anaemia, or an abdominal/epigastric mass) or new dyspepsia in older patients with additional risk factors, none of which are present here.', 1),
('c7000000-0000-0000-0000-000000000050', 'B', 'Reassure the patient with no testing or treatment, as symptoms are not concerning', false, 'Ruled out because although there are no red flags, active management (H. pylori testing and/or empirical PPI trial) is appropriate for symptomatic relief and to identify a treatable cause, rather than offering no action at all.', 2),
('c7000000-0000-0000-0000-000000000050', 'C', 'Start long-term high-dose PPI therapy indefinitely without any testing for H. pylori', false, $x$Ruled out because H. pylori testing (or a 'test and treat' strategy) is recommended alongside or instead of empirical PPI therapy, as eradicating H. pylori if present addresses the underlying cause rather than relying on indefinite acid suppression alone.$x$, 3),
('c7000000-0000-0000-0000-000000000050', 'D', 'Test for Helicobacter pylori infection and/or trial a proton pump inhibitor, as he does not meet criteria for urgent endoscopic referral', true, $x$Correct. In a patient with new dyspepsia but no alarm/red flag features (dysphagia, weight loss, GI bleeding, anaemia, persistent vomiting, or an abdominal mass) and no risk factors requiring urgent referral, initial management is a 'test and treat' approach for H. pylori and/or an empirical PPI trial, reserving urgent 2-week-wait endoscopy for those with red flag features or those over a certain age threshold with new dyspepsia.$x$, 4),
('c7000000-0000-0000-0000-000000000050', 'E', 'Arrange an abdominal ultrasound as the first investigation for dyspepsia', false, 'Ruled out because ultrasound is not the standard first-line investigation for uncomplicated dyspepsia without features suggesting biliary or pancreatic pathology; the standard approach is H. pylori testing and/or empirical PPI trial, with endoscopy reserved for red flag features.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('c7000000-0000-0000-0000-000000000001', 'IBS is a positive diagnosis based on the symptom pattern (abdominal pain related to defecation, altered stool form/frequency) once red flags are absent and simple tests (FBC, CRP, coeliac serology, faecal calprotectin) are normal.', 1),
('c7000000-0000-0000-0000-000000000001', 'First-line management of IBS is dietary and lifestyle modification before pharmacological therapy (antispasmodics, laxatives or antimotility agents depending on subtype) is considered.', 2),
('c7000000-0000-0000-0000-000000000001', 'Red flags mandating further investigation include rectal bleeding, unintentional weight loss, nocturnal symptoms, onset after age 50, or a family history of bowel or ovarian cancer.', 3),
('c7000000-0000-0000-0000-000000000002', 'In IBS-C, bulk-forming laxatives are first-line pharmacological therapy after dietary measures fail; osmotic laxatives are the next step if bulk-forming agents are unhelpful.', 1),
('c7000000-0000-0000-0000-000000000002', 'Loperamide (antimotility) is used in IBS-D, not IBS-C, and antispasmodics can be used for pain in either subtype.', 2),
('c7000000-0000-0000-0000-000000000002', 'Stimulant laxatives and opioids are not appropriate for long-term constipation management in IBS.', 3),
('c7000000-0000-0000-0000-000000000003', 'In simple chronic constipation without red flags, first-line treatment after dietary measures fail is an osmotic laxative, escalating to a stimulant laxative if needed.', 1),
('c7000000-0000-0000-0000-000000000003', 'Red flags requiring further investigation (e.g. colonoscopy) include rectal bleeding, unintentional weight loss, a palpable abdominal or rectal mass, or a change in bowel habit in an older patient without a clear benign cause.', 2),
('c7000000-0000-0000-0000-000000000003', 'Medications commonly contributing to constipation include opioids, calcium channel blockers, iron supplements and anticholinergics; a medication review is appropriate but should not delay standard laxative treatment.', 3),
('c7000000-0000-0000-0000-000000000004', 'Achalasia classically causes dysphagia to solids AND liquids from the outset, with regurgitation and weight loss, distinguishing it from mechanical strictures which affect solids first.', 1),
('c7000000-0000-0000-0000-000000000004', $x$Barium swallow in achalasia shows a dilated oesophagus with a smooth 'bird's beak' tapering at the gastro-oesophageal junction; manometry (showing absent peristalsis and failure of lower oesophageal sphincter relaxation) confirms the diagnosis.$x$, 2),
('c7000000-0000-0000-0000-000000000004', 'Endoscopy is required in all dysphagia presentations to exclude malignancy before attributing symptoms to a motility disorder.', 3),
('c7000000-0000-0000-0000-000000000005', $x$Diffuse oesophageal spasm causes intermittent chest pain and dysphagia with a characteristic 'corkscrew' oesophagus on barium swallow, reflecting uncoordinated simultaneous contractions.$x$, 1),
('c7000000-0000-0000-0000-000000000005', 'It is an important differential for cardiac chest pain, and should be considered after cardiac causes have been reasonably excluded.', 2),
('c7000000-0000-0000-0000-000000000005', 'Calcium channel blockers or nitrates may be used to reduce oesophageal spasm, though evidence for pharmacological treatment is limited.', 3),
('c7000000-0000-0000-0000-000000000006', 'Diabetic gastroparesis results from autonomic neuropathy affecting gastric motor function, and is more likely in patients with long-standing, poorly controlled diabetes and other microvascular complications.', 1),
('c7000000-0000-0000-0000-000000000006', 'Diagnosis requires excluding mechanical obstruction with endoscopy, then confirming delayed emptying with a gastric emptying study (scintigraphy).', 2),
('c7000000-0000-0000-0000-000000000006', 'Management includes optimising glycaemic control, dietary modification (small, frequent, low-fat/low-fibre meals) and prokinetic agents such as metoclopramide or domperidone if needed.', 3),
('c7000000-0000-0000-0000-000000000007', $x$Bile acid diarrhoea should be considered in chronic watery diarrhoea, particularly after cholecystectomy, ileal resection, or in association with Crohn's disease, and can mimic IBS-D.$x$, 1),
('c7000000-0000-0000-0000-000000000007', 'SeHCAT scanning quantifies bile acid retention; low retention (high loss) at 7 days supports the diagnosis.', 2),
('c7000000-0000-0000-0000-000000000007', 'Bile acid sequestrants such as colestyramine or colesevelam are the mainstay of treatment.', 3),
('c7000000-0000-0000-0000-000000000008', 'C. difficile infection should be suspected in any patient who develops diarrhoea during or after antibiotic treatment (classically co-amoxiclav, cephalosporins, clindamycin or fluoroquinolones), particularly if elderly or hospitalised.', 1),
('c7000000-0000-0000-0000-000000000008', 'Diagnosis is confirmed by stool testing for C. difficile toxin (glutamate dehydrogenase antigen plus toxin, or toxin PCR depending on local protocol).', 2),
('c7000000-0000-0000-0000-000000000008', 'Management includes stopping the causative antibiotic if possible, contact isolation, and oral vancomycin or fidaxomicin as first-line treatment (metronidazole is now second-line in UK guidance).', 3),
('c7000000-0000-0000-0000-000000000009', 'In cirrhotic patients presenting with upper GI bleeding, variceal haemorrhage should be assumed and treated with terlipressin and prophylactic antibiotics immediately, alongside resuscitation, prior to endoscopy.', 1),
('c7000000-0000-0000-0000-000000000009', 'Endoscopic variceal band ligation is the definitive treatment once the patient is stabilised; balloon tamponade or TIPS are used for uncontrolled bleeding.', 2),
('c7000000-0000-0000-0000-000000000009', 'A restrictive transfusion strategy (target haemoglobin around 70-80 g/L) is used in non-exsanguinating upper GI bleeding, as over-transfusion can worsen portal pressure and rebleeding risk.', 3),
('c7000000-0000-0000-0000-000000000010', 'Diverticular haemorrhage is the most common cause of acute lower GI bleeding in older adults and classically presents as sudden, painless, large-volume bright red or maroon bleeding.', 1),
('c7000000-0000-0000-0000-000000000010', 'Most diverticular bleeds stop spontaneously with conservative management (resuscitation and monitoring); colonoscopy is used both diagnostically and therapeutically if bleeding persists.', 2),
('c7000000-0000-0000-0000-000000000010', 'Ischaemic colitis typically presents with abdominal pain before bloody diarrhoea and often has vascular risk factors or a hypotensive precipitant.', 3),
('c7000000-0000-0000-0000-000000000011', 'Adhesions from previous abdominal or pelvic surgery are the most common cause of small bowel obstruction in adults.', 1),
('c7000000-0000-0000-0000-000000000011', 'Small bowel obstruction classically presents with colicky central pain, early vomiting (which becomes faeculent as it progresses), abdominal distension, and absolute constipation (in complete obstruction); AXR shows dilated small bowel loops with valvulae conniventes crossing the full width of the bowel.', 2),
('c7000000-0000-0000-0000-000000000011', $x$Initial management is fluid resuscitation, nasogastric decompression ('drip and suck'), and analgesia, with surgical review to assess for signs of strangulation requiring urgent operative intervention.$x$, 3),
('c7000000-0000-0000-0000-000000000012', $x$Perforated peptic ulcer classically presents with sudden severe abdominal pain, a rigid 'board-like' abdomen and peritonism; erect chest X-ray showing free air under the diaphragm supports the diagnosis.$x$, 1),
('c7000000-0000-0000-0000-000000000012', 'NSAIDs (and Helicobacter pylori infection) are major risk factors for peptic ulcer disease and its complications, including perforation and bleeding.', 2),
('c7000000-0000-0000-0000-000000000012', 'Management is immediate resuscitation, IV broad-spectrum antibiotics, analgesia and urgent surgical referral for likely laparotomy or laparoscopic repair; this is a time-critical surgical emergency.', 3),
('c7000000-0000-0000-0000-000000000013', $x$Toxic megacolon is a life-threatening complication of severe colitis (most often ulcerative colitis, but also Crohn's or infective colitis) defined by colonic dilation (typically >6 cm on AXR) with systemic toxicity.$x$, 1),
('c7000000-0000-0000-0000-000000000013', 'It carries a significant risk of colonic perforation and requires urgent involvement of both gastroenterology and colorectal surgery, IV corticosteroids, and close monitoring with a low threshold for surgery (colectomy) if there is no improvement within 72 hours or signs of deterioration.', 2),
('c7000000-0000-0000-0000-000000000013', 'Acute severe ulcerative colitis is assessed using criteria such as Truelove and Witts (stool frequency, blood, fever, tachycardia, anaemia, raised ESR/CRP) to guide the urgency of escalation.', 3),
('c7000000-0000-0000-0000-000000000014', $x$Most traveller's diarrhoea is self-limiting and managed conservatively with oral rehydration solution; antibiotics are reserved for severe, persistent, or bloody diarrhoea, high fever, or immunocompromise.$x$, 1),
('c7000000-0000-0000-0000-000000000014', 'Common causative organisms include enterotoxigenic E. coli, Campylobacter, Shigella and Salmonella; stool culture should be considered if symptoms are severe, persistent beyond a few days, or bloody.', 2),
('c7000000-0000-0000-0000-000000000014', 'Red flags warranting further assessment include high fever, bloody stools, signs of severe dehydration, or symptoms persisting beyond a week.', 3),
('c7000000-0000-0000-0000-000000000015', $x$Crohn's disease causes patchy, transmural inflammation that can affect any part of the GI tract (mouth to anus) with skip lesions and non-caseating granulomas on histology; the terminal ileum is a common site.$x$, 1),
('c7000000-0000-0000-0000-000000000015', 'Extraintestinal and associated features include oral ulcers, perianal disease (fistulae, abscesses), and an increased risk of strictures and fistula formation due to transmural involvement.', 2),
('c7000000-0000-0000-0000-000000000015', 'In contrast, ulcerative colitis causes continuous mucosal inflammation starting at the rectum, without granulomas, and does not typically involve the small bowel.', 3),
('c7000000-0000-0000-0000-000000000016', 'Ulcerative colitis causes continuous mucosal inflammation starting in the rectum and extending proximally without skip lesions, with crypt abscesses and architectural distortion on histology, and no granulomas.', 1),
('c7000000-0000-0000-0000-000000000016', 'Typical symptoms are bloody diarrhoea, urgency and tenesmus; severity is often classified with the Truelove and Witts criteria to guide management of an acute flare.', 2),
('c7000000-0000-0000-0000-000000000016', 'First-line treatment for mild-moderate UC flares is 5-aminosalicylates (topical and/or oral), with corticosteroids used for more significant flares not responding to aminosalicylates.', 3),
('c7000000-0000-0000-0000-000000000017', 'Truelove and Witts criteria classify severe UC as ≥6 bloody stools/day plus at least one of: fever >37.8C, HR >90 bpm, haemoglobin <105 g/L, or ESR >30 mm/hr (or CRP >30 in some adaptations).', 1),
('c7000000-0000-0000-0000-000000000017', 'Acute severe ulcerative colitis is a medical emergency requiring hospital admission, IV corticosteroids, VTE prophylaxis, and daily monitoring (including for toxic megacolon); rescue therapy (infliximab or ciclosporin) or surgery is considered if no response by 72 hours.', 2),
('c7000000-0000-0000-0000-000000000017', 'Stool cultures/C. difficile testing should be performed to exclude a superimposed infection before or alongside starting immunosuppression.', 3),
('c7000000-0000-0000-0000-000000000018', $x$Perianal fistulae are a recognised complication of Crohn's disease due to its transmural inflammatory nature, and MRI pelvis is the investigation of choice to map fistula anatomy.$x$, 1),
('c7000000-0000-0000-0000-000000000018', 'Management is typically combined: colorectal surgery for local sepsis control (e.g. seton insertion, drainage of abscesses) and gastroenterology for medical therapy (commonly anti-TNF biologics such as infliximab, which are particularly effective for fistulising disease).', 2),
('c7000000-0000-0000-0000-000000000018', 'Antibiotics (e.g. metronidazole or ciprofloxacin) may provide symptomatic benefit but do not replace definitive surgical and immunosuppressive management.', 3),
('c7000000-0000-0000-0000-000000000019', 'Azathioprine (and mercaptopurine) can cause bone marrow suppression (leucopenia, thrombocytopenia) and hepatotoxicity; regular full blood count and liver function monitoring is required, especially after dose changes.', 1),
('c7000000-0000-0000-0000-000000000019', 'TPMT (thiopurine methyltransferase) activity should ideally be checked before starting therapy, as low activity increases the risk of severe myelosuppression.', 2),
('c7000000-0000-0000-0000-000000000019', 'A significant unexplained drop in white cell count on a thiopurine should prompt withholding the drug and urgent reassessment, given the risk of progression to severe neutropenia and infection.', 3),
('c7000000-0000-0000-0000-000000000020', '5-aminosalicylates (e.g. mesalazine) are first-line for inducing and maintaining remission in mild-moderate ulcerative colitis, and reduce long-term colorectal cancer risk.', 1),
('c7000000-0000-0000-0000-000000000020', 'Topical (rectal) 5-ASA is particularly effective for distal/left-sided disease, often used in combination with oral therapy for more extensive disease.', 2),
('c7000000-0000-0000-0000-000000000020', 'Long-term corticosteroids are avoided for maintenance due to cumulative toxicity; thiopurines or biologics are reserved as escalation for steroid-dependent or more severe/refractory disease.', 3),
('c7000000-0000-0000-0000-000000000021', 'Erythema nodosum is an extraintestinal manifestation of IBD (and other conditions) that typically parallels intestinal disease activity, presenting as tender erythematous nodules, usually on the shins.', 1),
('c7000000-0000-0000-0000-000000000021', 'Pyoderma gangrenosum is another IBD-associated skin condition but is typically ulcerating and does not necessarily parallel bowel disease activity in the same way.', 2),
('c7000000-0000-0000-0000-000000000021', 'Other extraintestinal manifestations of IBD include enteropathic arthritis/spondyloarthropathy (relevant to her back symptoms), uveitis/episcleritis, and primary sclerosing cholangitis (more associated with ulcerative colitis).', 3),
('c7000000-0000-0000-0000-000000000022', 'Alcoholic hepatitis typically causes an AST:ALT ratio greater than 2 (unlike viral hepatitis, where ALT often exceeds AST), along with a raised GGT reflecting alcohol-related liver injury.', 1),
('c7000000-0000-0000-0000-000000000022', 'Severity can be assessed using scoring systems such as the Maddrey discriminant function, which helps determine whether corticosteroid therapy is indicated in severe alcoholic hepatitis.', 2),
('c7000000-0000-0000-0000-000000000022', 'Complete abstinence from alcohol is the single most important intervention, alongside nutritional support and screening for and managing withdrawal (e.g. with a chlordiazepoxide reducing regimen and thiamine).', 3),
('c7000000-0000-0000-0000-000000000023', 'A serum-ascites albumin gradient (SAAG) ≥11 g/L indicates portal hypertension as the cause of ascites (e.g. cirrhosis, heart failure); <11 g/L suggests other causes (e.g. malignancy, TB, pancreatitis).', 1),
('c7000000-0000-0000-0000-000000000023', 'Spontaneous bacterial peritonitis is diagnosed by an ascitic fluid neutrophil (polymorphonuclear) count ≥250 cells/microlitre, and treated empirically with IV antibiotics (commonly a third-generation cephalosporin) pending culture.', 2),
('c7000000-0000-0000-0000-000000000023', 'First-line management of cirrhotic ascites is sodium restriction plus diuretics (spironolactone ± furosemide); large-volume paracentesis with albumin cover and TIPS are reserved for tense or refractory ascites.', 3),
('c7000000-0000-0000-0000-000000000024', 'Hepatic encephalopathy in cirrhosis is often precipitated by infection, GI bleeding, constipation, electrolyte disturbance, or medication non-adherence/sedatives; identifying and treating the precipitant is essential alongside symptomatic treatment.', 1),
('c7000000-0000-0000-0000-000000000024', 'Lactulose is first-line treatment, reducing ammonia absorption; rifaximin may be added for recurrent or breakthrough episodes despite lactulose.', 2),
('c7000000-0000-0000-0000-000000000024', 'Sedatives, particularly benzodiazepines and opioids, should be avoided or used with caution in cirrhotic patients as they can precipitate or worsen encephalopathy.', 3),
('c7000000-0000-0000-0000-000000000025', 'Spontaneous bacterial peritonitis is diagnosed by an ascitic fluid neutrophil count ≥250 cells/microlitre in a patient with cirrhotic ascites, and treated promptly with empirical IV antibiotics (commonly third-generation cephalosporins).', 1),
('c7000000-0000-0000-0000-000000000025', 'IV albumin is given in addition to antibiotics in patients with renal impairment or more severe SBP to reduce the risk of hepatorenal syndrome and improve survival.', 2),
('c7000000-0000-0000-0000-000000000025', 'After an episode of SBP, secondary prophylaxis with a prophylactic antibiotic (e.g. ciprofloxacin or norfloxacin) is usually recommended to reduce recurrence risk.', 3),
('c7000000-0000-0000-0000-000000000026', 'Balloon tamponade (Sengstaken-Blakemore tube) is a temporary measure for uncontrolled variceal bleeding, used to stabilise the patient while arranging definitive treatment such as TIPS.', 1),
('c7000000-0000-0000-0000-000000000026', 'TIPS reduces portal pressure by creating a shunt between the portal and hepatic venous systems and is indicated for variceal bleeding refractory to endoscopic and pharmacological treatment.', 2),
('c7000000-0000-0000-0000-000000000026', 'Terlipressin and prophylactic antibiotics should be continued throughout the acute management of variceal haemorrhage, alongside escalation of definitive treatment when initial endoscopic therapy fails.', 3),
('c7000000-0000-0000-0000-000000000027', 'Paracetamol overdose management is guided by plasma paracetamol level (taken no earlier than 4 hours post-ingestion) plotted against the treatment nomogram; a level above the treatment line indicates IV N-acetylcysteine is required.', 1),
('c7000000-0000-0000-0000-000000000027', 'N-acetylcysteine works by replenishing hepatic glutathione stores, which detoxify the reactive metabolite (NAPQI) responsible for hepatocellular injury; it is most effective when started within 8 hours of ingestion but should still be given beyond this if indicated.', 2),
('c7000000-0000-0000-0000-000000000027', 'All patients presenting after intentional self-poisoning require psychiatric risk assessment once medically stable, in addition to the medical management of the overdose itself.', 3),
('c7000000-0000-0000-0000-000000000028', $x$Hereditary haemochromatosis classically presents with fatigue, bronze skin pigmentation, arthropathy (classically the second and third metacarpophalangeal joints), diabetes ('bronze diabetes'), and liver disease, due to HFE gene mutations causing iron overload.$x$, 1),
('c7000000-0000-0000-0000-000000000028', 'Diagnosis is supported by markedly raised ferritin with elevated transferrin saturation, confirmed with HFE genetic testing; liver biopsy may be used to assess fibrosis in some cases.', 2),
('c7000000-0000-0000-0000-000000000028', 'Treatment is regular venesection to reduce iron burden, with monitoring of ferritin levels; first-degree relatives should be offered screening given the autosomal recessive inheritance pattern.', 3),
('c7000000-0000-0000-0000-000000000029', 'Coeliac disease is screened for with anti-tissue transglutaminase (anti-tTG) IgA antibodies (checking total IgA to exclude deficiency), and confirmed with duodenal biopsy showing villous atrophy, crypt hyperplasia, and intraepithelial lymphocytosis.', 1),
('c7000000-0000-0000-0000-000000000029', 'Patients must continue eating gluten before both serological testing and biopsy, as a gluten-free diet started prematurely can cause false-negative results.', 2),
('c7000000-0000-0000-0000-000000000029', 'Coeliac disease is associated with dermatitis herpetiformis, iron-deficiency anaemia, osteoporosis, and an increased risk of enteropathy-associated T-cell lymphoma if untreated.', 3),
('c7000000-0000-0000-0000-000000000030', 'Pernicious anaemia results from autoimmune destruction of gastric parietal cells (or anti-intrinsic factor antibodies), impairing intrinsic factor-mediated B12 absorption in the terminal ileum, and is associated with other autoimmune conditions (e.g. autoimmune thyroid disease, vitiligo, type 1 diabetes).', 1),
('c7000000-0000-0000-0000-000000000030', 'B12 deficiency causes macrocytic anaemia with neurological features (peripheral neuropathy, subacute combined degeneration of the cord if severe/prolonged) and glossitis.', 2),
('c7000000-0000-0000-0000-000000000030', 'Diagnosis is supported by low serum B12 and intrinsic factor antibodies (more specific than parietal cell antibodies); treatment is with intramuscular B12 replacement (hydroxocobalamin), initially as a loading regimen.', 3),
('c7000000-0000-0000-0000-000000000031', 'Unexplained iron-deficiency anaemia in adults (particularly men and postmenopausal women) warrants urgent investigation to exclude gastrointestinal malignancy, even without overt bleeding or classic red flag symptoms.', 1),
('c7000000-0000-0000-0000-000000000031', 'Bidirectional endoscopy (colonoscopy and, depending on findings/symptoms, upper GI endoscopy) is typically used to identify occult sources of blood loss such as colorectal cancer, gastric cancer, or peptic ulceration.', 2),
('c7000000-0000-0000-0000-000000000031', 'Coeliac disease should also be excluded with serology as a treatable cause of iron deficiency, but this does not replace investigation for a gastrointestinal malignancy in at-risk patients.', 3),
('c7000000-0000-0000-0000-000000000032', 'Refeeding syndrome occurs when nutrition is reintroduced after a period of starvation/malnutrition, causing an insulin-driven intracellular shift of phosphate, potassium and magnesium, leading to potentially fatal hypophosphataemia, hypokalaemia and hypomagnesaemia.', 1),
('c7000000-0000-0000-0000-000000000032', 'Patients at high risk (e.g. chronic alcohol use, anorexia, prolonged fasting) should have feeding started cautiously at a reduced rate with careful electrolyte monitoring and correction, alongside prophylactic thiamine and vitamin B co-strong supplementation before and during refeeding.', 2),
('c7000000-0000-0000-0000-000000000032', 'Severe hypophosphataemia can cause muscle weakness (including respiratory muscle weakness), cardiac arrhythmias, and confusion, making early recognition and correction essential.', 3),
('c7000000-0000-0000-0000-000000000033', 'Malabsorptive bariatric procedures (e.g. Roux-en-Y gastric bypass) markedly increase the risk of fat-soluble vitamin (A, D, E, K) and mineral (calcium, iron, B12) deficiencies, requiring lifelong monitoring and supplementation.', 1),
('c7000000-0000-0000-0000-000000000033', 'Osteomalacia results from vitamin D deficiency causing impaired bone mineralisation, presenting with diffuse bone pain, proximal myopathy, low calcium/phosphate, low vitamin D, and secondary (compensatory) hyperparathyroidism.', 2),
('c7000000-0000-0000-0000-000000000033', 'Management includes vitamin D and calcium replacement, alongside reinforcing adherence to lifelong post-bariatric surgery supplementation regimens.', 3),
('c7000000-0000-0000-0000-000000000034', $x$Short bowel syndrome occurs when residual functional small bowel length is insufficient to maintain adequate nutrient, fluid and electrolyte absorption, often after extensive resection (e.g. for mesenteric ischaemia, Crohn's disease, or trauma).$x$, 1),
('c7000000-0000-0000-0000-000000000034', 'Severity depends on the remaining bowel length, the presence or absence of the colon and ileocaecal valve, and adaptation over time; severe cases require long-term parenteral nutrition (intestinal failure).', 2),
('c7000000-0000-0000-0000-000000000034', 'Management involves dietary modification, antimotility/antisecretory agents to reduce losses, and specialist intestinal failure unit input for nutritional support, with small bowel transplantation considered in select refractory cases.', 3),
('c7000000-0000-0000-0000-000000000035', 'Lactose intolerance results from relative lactase deficiency, causing undigested lactose to be fermented by colonic bacteria, producing bloating, flatulence and osmotic diarrhoea after consuming dairy products.', 1),
('c7000000-0000-0000-0000-000000000035', 'Diagnosis can be supported by a hydrogen breath test or a trial of dietary lactose elimination followed by rechallenge; it is distinct from milk protein allergy, which involves an immune-mediated reaction.', 2),
('c7000000-0000-0000-0000-000000000035', 'Management is primarily dietary lactose restriction, with lactase enzyme replacement supplements as an option for symptom control when dairy cannot be fully avoided.', 3),
('c7000000-0000-0000-0000-000000000036', 'Acute pancreatitis is diagnosed by 2 of 3 features: characteristic epigastric pain radiating to the back, serum lipase or amylase more than 3 times the upper limit of normal, and characteristic imaging findings.', 1),
('c7000000-0000-0000-0000-000000000036', $x$Gallstones and alcohol are the two most common causes of acute pancreatitis in the UK; other causes are remembered by mnemonics such as 'GET SMASHED' (gallstones, ethanol, trauma, steroids, mumps, autoimmune, scorpion sting, hyperlipidaemia/hypercalcaemia, ERCP, drugs).$x$, 2),
('c7000000-0000-0000-0000-000000000036', 'Initial management is aggressive IV fluid resuscitation, analgesia, and monitoring for severity, with early consideration of the underlying cause (e.g. biliary imaging if gallstones are suspected).', 3),
('c7000000-0000-0000-0000-000000000037', 'Severity in acute pancreatitis is assessed with validated scoring systems (Glasgow-Imrie criteria, APACHE II, or a CRP >150 mg/L at 48 hours) rather than a single symptom or biochemical marker.', 1),
('c7000000-0000-0000-0000-000000000037', $x$Glasgow-Imrie criteria include: PaO2, age, neutrophils (WCC), calcium, renal function (urea), enzymes (LDH/AST), albumin, and glucose ('PANCREAS' mnemonic); three or more positive criteria within 48 hours indicates severe pancreatitis.$x$, 2),
('c7000000-0000-0000-0000-000000000037', 'Patients identified as having severe pancreatitis require escalation to a higher level of care (HDU/ICU) for close monitoring and management of potential complications such as organ failure, necrosis and infection.', 3),
('c7000000-0000-0000-0000-000000000038', 'Chronic pancreatitis, most commonly caused by long-term alcohol excess, causes progressive pancreatic damage leading to recurrent pain, exocrine insufficiency (steatorrhoea, malabsorption, weight loss) and eventually endocrine insufficiency (diabetes).', 1),
('c7000000-0000-0000-0000-000000000038', 'CT imaging classically shows pancreatic calcification and ductal dilation, useful for confirming the diagnosis.', 2),
('c7000000-0000-0000-0000-000000000038', 'Management includes alcohol cessation, analgesia, pancreatic enzyme replacement therapy for exocrine insufficiency, and monitoring for diabetes; there is an increased long-term risk of pancreatic cancer.', 3),
('c7000000-0000-0000-0000-000000000039', $x$Acute cholecystitis presents with constant RUQ pain (often radiating to the right shoulder), fever, and a positive Murphy's sign, typically due to gallstone obstruction of the cystic duct; ultrasound shows gallbladder wall thickening and pericholecystic fluid.$x$, 1),
('c7000000-0000-0000-0000-000000000039', $x$This is distinguished from biliary colic (pain without inflammation/infection) and from ascending cholangitis (which involves the common bile duct and classically presents with Charcot's triad of fever, jaundice and RUQ pain).$x$, 2),
('c7000000-0000-0000-0000-000000000039', 'Management is IV antibiotics and analgesia, with early laparoscopic cholecystectomy (ideally within 1 week of symptom onset) being the definitive treatment.', 3),
('c7000000-0000-0000-0000-000000000040', $x$Ascending cholangitis presents with Charcot's triad (fever, jaundice, RUQ pain); the addition of hypotension and confusion (Reynolds' pentad) indicates severe, life-threatening suppurative cholangitis.$x$, 1),
('c7000000-0000-0000-0000-000000000040', 'Management is IV fluids, IV antibiotics, and urgent biliary decompression (usually ERCP with sphincterotomy and stone extraction/stenting), which should not be delayed once the patient is stabilised.', 2),
('c7000000-0000-0000-0000-000000000040', 'This is distinguished from simple biliary colic or uncomplicated cholecystitis by the presence of jaundice and common bile duct dilation/obstruction with stones, indicating involvement of the biliary tree itself rather than just the gallbladder.', 3),
('c7000000-0000-0000-0000-000000000041', $x$Courvoisier's sign (painless jaundice with a palpable gallbladder) suggests malignant obstruction of the common bile duct (e.g. pancreatic head or cholangiocarcinoma) rather than gallstones, which typically cause a painful, fibrotic (non-palpable) gallbladder.$x$, 1),
('c7000000-0000-0000-0000-000000000041', $x$The 'double duct sign' (dilation of both the common bile duct and pancreatic duct) on imaging is characteristic of a pancreatic head mass obstructing both ducts near the ampulla.$x$, 2),
('c7000000-0000-0000-0000-000000000041', 'Pancreatic cancer often presents late with painless jaundice, weight loss and new-onset diabetes; prognosis is often poor as many present with locally advanced or metastatic disease.', 3),
('c7000000-0000-0000-0000-000000000042', 'Gallstone ileus results from a large gallstone eroding through a cholecysto-enteric fistula and causing mechanical small bowel obstruction, most often at the terminal ileum (the narrowest point of the small bowel).', 1),
('c7000000-0000-0000-0000-000000000042', $x$Rigler's triad on imaging comprises: small bowel obstruction, pneumobilia, and an ectopic gallstone visible outside the biliary tree.$x$, 2),
('c7000000-0000-0000-0000-000000000042', 'Management is surgical, typically enterotomy and stone extraction, with management of the fistula often deferred to a later date given the typically frail patient population.', 3),
('c7000000-0000-0000-0000-000000000043', 'Typical GORD symptoms without red flags can be managed empirically in primary care with lifestyle advice and a PPI trial, without requiring initial endoscopy.', 1),
('c7000000-0000-0000-0000-000000000043', 'Red flags requiring urgent (2-week-wait) endoscopic referral include dysphagia, weight loss, persistent vomiting, iron-deficiency anaemia, or an epigastric mass, particularly in patients over 55.', 2),
('c7000000-0000-0000-0000-000000000043', 'PPIs are first-line pharmacological therapy for GORD due to superior acid suppression compared with H2 receptor antagonists.', 3),
('c7000000-0000-0000-0000-000000000044', 'H. pylori infection is a major cause of peptic ulcer disease and is treated with eradication therapy (PPI plus two antibiotics), which reduces ulcer recurrence and complications.', 1),
('c7000000-0000-0000-0000-000000000044', 'Duodenal ulcers classically cause pain relieved by eating (with pain recurring a few hours later or at night), while gastric ulcers classically cause pain worsened by eating.', 2),
('c7000000-0000-0000-0000-000000000044', 'NSAIDs and H. pylori are the two major causes of peptic ulcer disease; NSAID use should be reviewed and stopped or substituted with PPI cover if it must continue.', 3),
('c7000000-0000-0000-0000-000000000045', $x$Barrett's oesophagus is a premalignant condition where the normal squamous oesophageal epithelium is replaced by columnar epithelium with intestinal metaplasia, arising from chronic GORD, and carries an increased risk of oesophageal adenocarcinoma.$x$, 1),
('c7000000-0000-0000-0000-000000000045', $x$Management of non-dysplastic Barrett's is PPI therapy and regular endoscopic surveillance to detect dysplasia early; the presence of dysplasia (especially high-grade) prompts endoscopic therapy (e.g. radiofrequency ablation, endoscopic resection).$x$, 2),
('c7000000-0000-0000-0000-000000000045', 'Surveillance intervals depend on segment length and the presence/grade of dysplasia found on biopsy.', 3),
('c7000000-0000-0000-0000-000000000046', $x$Squamous cell carcinoma of the oesophagus is strongly associated with smoking and alcohol use and tends to occur in the proximal/mid-oesophagus, whereas adenocarcinoma (associated with Barrett's oesophagus/GORD) tends to occur distally.$x$, 1),
('c7000000-0000-0000-0000-000000000046', $x$Progressive dysphagia (solids then liquids) with weight loss is a classic 'alarm' presentation requiring urgent endoscopic assessment and biopsy.$x$, 2),
('c7000000-0000-0000-0000-000000000046', 'Staging (CT, endoscopic ultrasound, PET-CT as indicated) is essential after histological diagnosis to guide whether treatment is curative (surgery +/- neoadjuvant chemoradiotherapy) or palliative.', 3),
('c7000000-0000-0000-0000-000000000047', 'Gastric adenocarcinoma often presents late with vague symptoms (dyspepsia, early satiety, weight loss); risk factors include H. pylori infection, smoking, and a diet high in smoked/processed foods.', 1),
('c7000000-0000-0000-0000-000000000047', 'Staging (CT +/- staging laparoscopy to detect occult peritoneal metastases) guides treatment planning, which may involve surgery (with perioperative chemotherapy) for resectable disease or palliative treatment for advanced/metastatic disease.', 2),
('c7000000-0000-0000-0000-000000000047', 'Any new dyspepsia in an older patient, particularly with weight loss or other red flags, warrants prompt endoscopic investigation to exclude malignancy.', 3),
('c7000000-0000-0000-0000-000000000048', 'Zollinger-Ellison syndrome is caused by a gastrin-secreting neuroendocrine tumour (gastrinoma), leading to gastric acid hypersecretion, recurrent/refractory peptic ulceration, and diarrhoea.', 1),
('c7000000-0000-0000-0000-000000000048', 'Diagnosis is supported by markedly elevated fasting gastrin, with a paradoxical further rise after secretin stimulation (secretin normally suppresses gastrin release from healthy G cells, but gastrinoma cells respond abnormally).', 2),
('c7000000-0000-0000-0000-000000000048', 'It can occur sporadically or as part of multiple endocrine neoplasia type 1 (MEN1); management includes high-dose PPI therapy for acid control and localisation/resection of the tumour where possible.', 3),
('c7000000-0000-0000-0000-000000000049', 'Mallory-Weiss tears result from a sudden increase in intra-abdominal pressure during forceful vomiting or retching, classically following alcohol excess, causing a longitudinal mucosal tear at the gastro-oesophageal junction.', 1),
('c7000000-0000-0000-0000-000000000049', 'Most Mallory-Weiss tears are self-limiting and managed conservatively, as bleeding is usually minor and stops spontaneously; endoscopic therapy is reserved for ongoing active bleeding.', 2),
('c7000000-0000-0000-0000-000000000049', 'This is distinguished from Boerhaave syndrome, a full-thickness oesophageal rupture that is a surgical emergency presenting with severe pain and systemic illness, requiring urgent recognition and different management.', 3),
('c7000000-0000-0000-0000-000000000050', $x$Uncomplicated dyspepsia without red flags is managed with a 'test and treat' approach for H. pylori and/or an empirical PPI trial, without the need for endoscopy.$x$, 1),
('c7000000-0000-0000-0000-000000000050', 'Red flags mandating urgent (2-week-wait) endoscopic referral include dysphagia, weight loss, persistent vomiting, unexplained iron-deficiency anaemia, and an epigastric mass; new dyspepsia in patients above a certain age (commonly 55) with additional risk factors also warrants referral per local/NICE guidance.', 2),
('c7000000-0000-0000-0000-000000000050', $x$H. pylori 'test and treat' involves testing (e.g. stool antigen or urea breath test) followed by eradication therapy if positive, addressing the underlying cause of many cases of dyspepsia and peptic ulcer disease.$x$, 3);
